window.I18N = {"ar": {"nav_how": "كيف يعمل", "nav_learn": "تعلّم", "nav_carry": "للحمل", "nav_harness": "الأحزمة", "nav_wear": "للارتداء", "nav_space": "المساحات", "nav_custom": "حسب الطلب", "hero_h1": "في الهواء ما يفيض عن الحاجة. نحن نُبقيه في الخارج.", "hero_p": "مصنوعة يدويًا في برلين، ومفصّلة خصيصًا لكل شخص. كل قطعة من Heisenbag Shield تحمل قفص فاراداي كاملًا منسوجًا في القماش. لهاتفك، لسيارتك، لاستوديوك، لبيتك. لا شيء يحتاج إلى شحن، ولا شيء يحتاج إلى تشغيل، ولا تطبيق عليك أن تثق به.", "hero_cta": "شاهد القطع الـ 24", "how_h2": "قفص معدني، منسوج في القماش.", "how_p": "عمر هذه الفيزياء 190 عامًا، ولا يُغلب. كل ما فعلناه أننا جعلناها قابلة للارتداء.", "step1": "<b>موجات الراديو كهرباء تسري في الهواء.</b> كل مكالمة، وكل إشارة GPS، وكل حزمة LTE هي مجال كهربائي يبحث عن هوائي هاتفك.", "step2": "<b>الشبكة الموصلة تبتلع المجالات الكهربائية.</b> بطانة كل منتج من Shield نسيج دقيق من الفضة والمعدن. تنساب الموجات القادمة من حوله، ولا تعبره أبدًا.", "step3": "<b>ما لا يستطيع الدخول لا يستطيع تتبّعك.</b> لا تصل أي إشارة إلى الجهاز، فلا يُبلغ الجهاز عن شيء: لا موقع، ولا اتصال بالبرج، ولا بيانات.", "step4": "<b>لا بطارية، لا تطبيق، لا زرّ إيقاف قد تنساه.</b> يعمل القفص بما هو عليه، لا بما يفعله. لا يمكن تحديثه أو اختراقه أو إطفاؤه.", "learn_h2": "تعرّف على الفيزياء.", "learn_p": "ثلاث أفكار تفسّر كل ما نصنعه. ما إن تراها، لن تنظر إلى هاتف بالطريقة نفسها أبدًا.", "learn1_h": "1. الموجات", "learn1_p": "الراديو ضوء لا تراه العين. كلاهما الشيء ذاته: مجالات كهربائية تتموّج عبر الفضاء. هاتفك، والـ wifi لديك، وقمر GPS الخاص بك، وضوء الشمس على الطاولة: عائلة واحدة من الموجات بأطوال مختلفة. لا شيء غامض، وكل شيء قابل للقياس.", "learn2_h": "2. الضوء", "learn2_p": "يشطر المنشور شعاعًا واحدًا إلى ألوان كثيرة لأن كل طول موجي ينكسر بشكل مختلف. الطول الموجي يحسم كل شيء: الموجات الطويلة تعبر الجدران، والقصيرة تحمل البيانات. ليست 5G وLTE وBluetooth سوى ألوان من الراديو، ومثل كل لون، يستطيع جدار أن يوقفها.", "learn3_h": "3. الإرسال", "learn3_p": "هاتفك والبرج يتصايحان بلا انقطاع، حتى وأنت نائم. بهذا الصياح المتبادل تعثر عليك الشبكات، وتسعّرك، وتتبعك. لُفّ الهاتف بقفص موصل، ولن يصل الصياح أبدًا. الصمت ليس إعدادًا. إنه هندسة.", "carry_h2": "للحمل.", "carry_p": "ثماني حقائب وأكياس، مخيطة باليد. كل منها يُغلق على القفص إغلاقًا تامًا، لأن قفص فاراداي فيه فجوة ليس إلا حقيبة.", "p_holster": "يُلبس على الحزام. يُسحب الهاتف بحركة واحدة، ويُختم بطيّة واحدة.", "p_sling": "تُحمل على الجسد بشكل مائل، عاليًا على الصدر. المفاتيح، البطاقة، الهاتف: في عتمة تامة.", "p_tote": "رفيق كل يوم. جيب واحد في الداخل يبتلع الهاتف كاملًا.", "p_sleeve": "للجهاز اللوحي والحاسوب المحمول. اجتماعات بلا جمهور.", "p_backpack": "بإغلاق ملفوف، سعة 20 لترًا. جيب قفص واحد، ومنطقة صامتة مضمونة.", "p_weekender": "حقيبة سفر بمقاس المقصورة. عبور الحدود بلا أثر للبيانات.", "p_keyfob": "يُخرج مفتاح سيارتك من الأثير. لصوص الترحيل لا ينالون سوى الصمت.", "p_wallet": "للبطاقات والنقود. NFC وRFID وأجهزة السرقة، كلها خارج الباب.", "harness_h2": "الأحزمة.", "harness_p": "تُرتدى، لا تُحمل. ثلاثة أحزمة تُبقي الهاتف على جسدك وبعيدًا عن الأثير حتى تقرر غير ذلك.", "p_harness": "حزام مائل مع جيب مُقفَص. دائمًا في متناول يدك، ولا يتصل أبدًا.", "p_chestrig": "جيب قفص أمامي كامل، وأشرطة عملية. عدّة الاستوديو والمسرح.", "p_wrist": "سوار للمعصم بجيب قفص صغير. للمفاتيح، للبطاقات، لأمسية هادئة.", "wear_h2": "للارتداء.", "wear_p": "خمس قطع ملابس خيط القفص في جيبها وقلنسوتها وحافتها. ترتديها كأي شيء آخر؛ وتعمل كما لا يعمل أي شيء آخر.", "p_hoodie": "جيب الكنغر منطقة صامتة. الهاتف في الداخل، والعالم في الخارج.", "p_parka": "جيوب عميقة مُقفَصة، صامدة للعواصف من الخارج، عازلة للإشارة من الداخل.", "p_cap": "ست قطع، وجيب واحد خفي. القبعة الهادئة.", "p_beanie": "حياكة من الخارج، وفضة من الداخل. شتاء بلا تتبّع.", "p_scarf": "يلفّ الهاتف الذي نسيت أن تطفئه.", "space_h2": "المساحات.", "space_p": "ثماني قطع للبيت والمكتب والسفر. من ستارة تحجب نافذة بالكامل إلى خيمة يبقى فيها الحديث حديثًا.", "p_tent": "غرفة خصوصية تُنصب في لحظة، لشخصين. لا شيء يدخل، لا شيء يخرج.", "p_curtain": "لوح واحد، بالطول الكامل. النافذة تكفّ عن الإصغاء.", "p_canopy": "ناموسية لسرير الرضيع. أصغر النائمين، أهدأ هواء.", "p_blanket": "غطاء للأريكة. الأجهزة تحته تختفي.", "p_cone": "مخروط للطاولة في الاجتماعات. الهواتف في الداخل، والأذهان حاضرة.", "p_sleepbox": "صندوق بجانب السرير. الهاتف ينام قبلك.", "p_keybox": "صندوق للمدخل. كل مفتاح في البيت، بعيدًا عن الأثير.", "p_router": "غطاء جرسيّ للـ wifi. الوضع الليلي، تفرضه الفيزياء.", "custom_h2": "حسب الطلب. نحجب أي شيء.", "custom_p": "كل قطعة مصنوعة يدويًا ومفصّلة خصيصًا لك. صِف ما ينبغي أن يصمت، فنرسمه بأسلوبنا هنا في المحادثة، وحين تحب الرسم، يخيطه أناس حقيقيون ويشحنونه إلى أنحاء العالم.", "p_carcover": "تختفي سيارتك من كل شبكة وهي نائمة.", "p_studio": "استوديوهات تسجيل، مختبرات، قاعات اجتماعات. جدران تحبس أنفاسها.", "on_request1": "عند الطلب", "p_research": "توهين مُقاس للمختبرات والعيادات ولكل من يحتاج إلى اليقين.", "on_request2": "عند الطلب", "p_anything": "ستائر، أغطية، ملابس، حاويات. إن استطعت وصفه، استطعنا حجبه.", "on_request3": "عند الطلب", "custom_cta": "ارسم قطعتك الخاصة", "why_h2": "الجميع في متناول الوصول. ولا أحد تقريبًا يختار متى.", "why_p1": "هاتفك يتحدث إلى الأبراج والأقمار الصناعية والمنارات والتطبيقات على مدار الساعة. يفعل ذلك <b>في جيبك، وعلى منضدة سريرك، وفي اجتماعاتك</b>. وضع الطيران وعدٌ من الشركات نفسها التي تجني المال من موقعك. أما قفص فاراداي فليس وعدًا. إنه فيزياء.", "why_p2": "كل قطعة Shield مصنوعة يدويًا، ومبطّنة بقماش بولي أميد مطلي بالفضة منسوج في ألمانيا، يوفّر توهينًا بمقدار 60 dB وأكثر من 200 MHz إلى 14 GHz: 5G وLTE وGPS وwifi وBluetooth وNFC. صحفيون يعبرون الحدود، محامون في مفاوضات، فنانو تسجيل، آباء يعلّمون أطفالهم معنى الانتباه: جميعهم يحتاجون إلى لحظة واحدة يكون فيها الجهاز ببساطة <b>غير موجود</b>.", "why_p3": "اللايقين، عن قصد.", "footer_l": "HEISENBAG — مصنوعة يدويًا في برلين، وتُشحن إلى أنحاء العالم", "chat_fab": "ارسم قطعتك", "chat_title": "صِف قطعتك. ونحن نرسمها.", "chat_btn": "ارسم", "chat_hint": "الرسم مجاني. إن أحببته، نصنعه باليد ونشحنه إلى أنحاء العالم.", "chat_ph": "حقيبة غيتار محجوبة، من جلد داكن…", "chat_wait": "جارٍ الرسم، لحظة واحدة…", "chat_order": "اطلب هذه القطعة", "chat_fail": "تعذّر الرسم، حاول مرة أخرى."}, "bn": {"nav_how": "কীভাবে কাজ করে", "nav_learn": "জানুন", "nav_carry": "বহন", "nav_harness": "হারনেস", "nav_wear": "পরিধান", "nav_space": "পরিসর", "nav_custom": "কাস্টম", "hero_h1": "চারপাশে বড় বেশি কিছু উড়ে বেড়াচ্ছে। আমরা তা বাইরে রাখি।", "hero_p": "বার্লিনে হাতে তৈরি, প্রত্যেকের জন্য আলাদা করে বানানো। প্রতিটি Heisenbag Shield পণ্যের কাপড়ে বোনা আছে একটি পূর্ণাঙ্গ ফ্যারাডে খাঁচা। আপনার ফোন, আপনার গাড়ি, আপনার স্টুডিও, আপনার ঘরের জন্য। চার্জ দেওয়ার কিছু নেই, চালু করার কিছু নেই, ভরসা করার মতো কোনো অ্যাপ নেই।", "hero_cta": "২৪টি পণ্য দেখুন", "how_h2": "ধাতব খাঁচা, কাপড়ে বোনা।", "how_p": "এই পদার্থবিদ্যা ১৯০ বছরের পুরোনো এবং অপরাজেয়। আমরা শুধু একে পরার উপযোগী করেছি।", "step1": "<b>রেডিও তরঙ্গ হলো বাতাসে ভাসমান বিদ্যুৎ।</b> প্রতিটি কল, প্রতিটি GPS পিং, প্রতিটি LTE প্যাকেট একটি বৈদ্যুতিক ক্ষেত্র, যা আপনার ফোনের অ্যান্টেনা খুঁজছে।", "step2": "<b>পরিবাহী জাল বৈদ্যুতিক ক্ষেত্রকে গ্রাস করে।</b> প্রতিটি Shield পণ্যের আস্তরণ রুপা ও ধাতুর সূক্ষ্ম বুনন। আগত তরঙ্গ এর চারপাশ দিয়ে বয়ে যায়, কখনো ভেদ করে না।", "step3": "<b>যা ভেতরে ঢুকতে পারে না, তা আপনাকে অনুসরণ করতে পারে না।</b> কোনো সিগন্যাল ডিভাইসে পৌঁছায় না, তাই ডিভাইস কিছুই জানায় না: না অবস্থান, না টাওয়ারের সঙ্গে সংযোগ, না ডেটা।", "step4": "<b>কোনো ব্যাটারি নেই, কোনো অ্যাপ নেই, ভুলে যাওয়ার মতো কোনো সুইচ নেই।</b> খাঁচাটি কাজ করে সে যা, তার জোরে; সে যা করে, তার জোরে নয়। একে আপডেট, হ্যাক বা বন্ধ করা যায় না।", "learn_h2": "পদার্থবিদ্যাটা জানুন।", "learn_p": "তিনটি ধারণা আমাদের তৈরি সবকিছুর ব্যাখ্যা দেয়। একবার দেখলে, ফোনের দিকে আর কখনো আগের মতো তাকাবেন না।", "learn1_h": "১. তরঙ্গ", "learn1_p": "রেডিও হলো এমন আলো যা চোখে দেখা যায় না। দুটোই একই জিনিস: মহাশূন্যে ঢেউ তোলা বৈদ্যুতিক ক্ষেত্র। আপনার ফোন, আপনার wifi, আপনার GPS স্যাটেলাইট, টেবিলের ওপর পড়া রোদ: একই পরিবারের তরঙ্গ, শুধু দৈর্ঘ্য ভিন্ন। রহস্যময় কিছু নয়, সবই পরিমাপযোগ্য।", "learn2_h": "২. আলো", "learn2_p": "প্রিজম একটি আলোকরশ্মিকে অনেক রঙে ভাগ করে, কারণ প্রতিটি তরঙ্গদৈর্ঘ্য ভিন্নভাবে বাঁকে। তরঙ্গদৈর্ঘ্যই সব ঠিক করে: দীর্ঘ তরঙ্গ দেয়াল ভেদ করে যায়, ছোট তরঙ্গ তথ্য বহন করে। 5G, LTE আর Bluetooth রেডিওর রঙ মাত্র, আর সব রঙের মতোই একটি দেয়াল এদের থামাতে পারে।", "learn3_h": "৩. সম্প্রচার", "learn3_p": "আপনার ফোন আর টাওয়ার অবিরাম একে অপরকে ডেকে চলে, এমনকি আপনি যখন ঘুমিয়ে থাকেন তখনও। এই দুই দিকের ডাকাডাকি দিয়েই নেটওয়ার্ক আপনাকে খুঁজে পায়, আপনার দাম ঠিক করে, আপনাকে অনুসরণ করে। ফোনটিকে একটি পরিবাহী খাঁচায় মুড়ে দিন, সেই ডাক আর কখনো পৌঁছাবে না। নীরবতা কোনো সেটিং নয়। এটি জ্যামিতি।", "carry_h2": "বহন।", "carry_p": "আটটি ব্যাগ ও পাউচ, হাতে সেলাই করা। প্রতিটি খাঁচার ওপর সম্পূর্ণভাবে বন্ধ হয়, কারণ ফাঁক থাকা ফ্যারাডে খাঁচা নিছক একটি ব্যাগ।", "p_holster": "বেল্টে পরার জন্য। এক টানে ফোন বের, এক ভাঁজে বন্ধ।", "p_sling": "ক্রসবডি, বুকের ওপর উঁচুতে। চাবি, কার্ড, ফোন: অন্ধকারে।", "p_tote": "প্রতিদিনের সঙ্গী। ভেতরের একটি পকেট পুরো ফোনটিকে গিলে ফেলে।", "p_sleeve": "ট্যাবলেট ও ল্যাপটপের জন্য। শ্রোতাহীন মিটিং।", "p_backpack": "রোল-টপ, ২০ লিটার। একটি খাঁচা-পকেট, নিশ্চিত ডেড জোন।", "p_weekender": "কেবিন-সাইজের ডাফেল। তথ্যের কোনো চিহ্ন ছাড়াই সীমান্ত পারাপার।", "p_keyfob": "আপনার গাড়ির চাবিকে তরঙ্গ থেকে সরিয়ে নেয়। রিলে চোরেরা পায় শুধু নীরবতা।", "p_wallet": "কার্ড ও নগদ টাকা। NFC, RFID আর স্কিমার বাইরে আটকে থাকে।", "harness_h2": "হারনেস।", "harness_p": "বহন নয়, পরিধান। তিনটি হারনেস যা ফোনকে আপনার শরীরে রাখে আর তরঙ্গ থেকে দূরে, যতক্ষণ না আপনি অন্যথা ঠিক করেন।", "p_harness": "খাঁচা-পাউচসহ ক্রসবডি হারনেস। সবসময় হাতের কাছে, কখনো অনলাইনে নয়।", "p_chestrig": "সামনে পূর্ণ খাঁচা-পকেট, ইউটিলিটি স্ট্র্যাপ। স্টুডিও ও মঞ্চের রিগ।", "p_wrist": "ছোট খাঁচা-পকেটসহ কব্জির স্ট্র্যাপ। চাবি, কার্ড আর একটি শান্ত সন্ধ্যার জন্য।", "wear_h2": "পরিধান।", "wear_p": "পাঁচটি পোশাক, যার পকেট, হুড আর কিনারায় খাঁচা সেলাই করা। আর সব পোশাকের মতোই পরবেন; কাজ করবে অন্য কোনোটির মতো নয়।", "p_hoodie": "ক্যাঙ্গারু পকেটটি একটি ডেড জোন। ফোন ভেতরে, পৃথিবী বাইরে।", "p_parka": "গভীর খাঁচা-পকেট, বাইরে ঝড়রোধী, ভেতরে সিগন্যালরোধী।", "p_cap": "ছয়টি প্যানেল, একটি লুকানো পকেট। নিঃশব্দ ক্যাপ।", "p_beanie": "বাইরে বোনা উল, ভেতরে রুপা। শীত, অনুসরণহীন।", "p_scarf": "বন্ধ করতে ভুলে যাওয়া ফোনটিকে মুড়ে রাখে।", "space_h2": "পরিসর।", "space_p": "ঘর, অফিস ও ভ্রমণের জন্য আটটি পণ্য। জানালা অন্ধকার করে দেওয়া পর্দা থেকে এমন তাঁবু পর্যন্ত, যেখানে কথোপকথন কথোপকথনই থেকে যায়।", "p_tent": "দুজনের জন্য পপ-আপ প্রাইভেসি রুম। কিছু ভেতরে নয়, কিছু বাইরে নয়।", "p_curtain": "একটি প্যানেল, পূর্ণ দৈর্ঘ্য। জানালা আর কান পাতে না।", "p_canopy": "দোলনার চাঁদোয়া। সবচেয়ে ছোট ঘুমন্তজন, সবচেয়ে শান্ত বাতাস।", "p_blanket": "সোফার জন্য একটি চাদর। এর নিচের ডিভাইসগুলো উধাও।", "p_cone": "মিটিংয়ের জন্য টেবিলের ওপরের কোন। ফোন ভেতরে, মন উপস্থিত।", "p_sleepbox": "বিছানার পাশের বাক্স। আপনার আগে ফোন ঘুমিয়ে পড়ে।", "p_keybox": "প্রবেশপথের বাক্স। ঘরের প্রতিটি চাবি, তরঙ্গের বাইরে।", "p_router": "wifi-এর জন্য একটি ঢাকনা। নাইট মোড, পদার্থবিদ্যার নিয়মে।", "custom_h2": "কাস্টম। আমরা যেকোনো কিছু সুরক্ষিত করি।", "custom_p": "প্রতিটি পণ্য হাতে তৈরি এবং আপনার জন্য আলাদা করে বানানো। কী নীরব থাকা উচিত তা বর্ণনা করুন, আমরা এখানেই চ্যাটে আমাদের শৈলীতে তা আঁকব, আর ছবিটি আপনার মনে ধরলে সত্যিকারের মানুষ তা সেলাই করে বিশ্বজুড়ে পাঠিয়ে দেবে।", "p_carcover": "আপনার গাড়ি ঘুমিয়ে থাকার সময় প্রতিটি নেটওয়ার্ক থেকে অদৃশ্য হয়ে যায়।", "p_studio": "রেকর্ডিং স্টুডিও, ল্যাব, মিটিং রুম। দেয়াল, যা শ্বাস ধরে রাখে।", "on_request1": "অনুরোধে", "p_research": "ল্যাব, ক্লিনিক এবং নিশ্চয়তা যাঁর প্রয়োজন তাঁদের জন্য পরিমাপকৃত অ্যাটেনুয়েশন।", "on_request2": "অনুরোধে", "p_anything": "পর্দা, আবরণ, পোশাক, ঘের। আপনি বর্ণনা করতে পারলে, আমরা তা সুরক্ষিত করতে পারি।", "on_request3": "অনুরোধে", "custom_cta": "নিজের পণ্যটি আঁকুন", "why_h2": "সবার কাছেই পৌঁছানো যায়। প্রায় কেউই বেছে নিতে পারে না কখন।", "why_p1": "আপনার ফোন দিনরাত টাওয়ার, স্যাটেলাইট, বিকন আর অ্যাপের সঙ্গে কথা বলে। এটা ঘটে <b>আপনার পকেটে, আপনার বিছানার পাশে, আপনার মিটিংয়ে</b>। এয়ারপ্লেন মোড হলো সেই একই কোম্পানিগুলোর প্রতিশ্রুতি, যারা আপনার অবস্থান থেকে মুনাফা করে। ফ্যারাডে খাঁচা কোনো প্রতিশ্রুতি নয়। এটা পদার্থবিজ্ঞান।", "why_p2": "প্রতিটি Shield পণ্য হাতে তৈরি, জার্মানিতে বোনা রুপা-প্রলেপিত পলিঅ্যামাইড কাপড়ে আস্তরিত, যা 200 MHz থেকে 14 GHz পর্যন্ত 60 dB বা তার বেশি অ্যাটেনুয়েট করে: 5G, LTE, GPS, wifi, Bluetooth, NFC। সীমান্ত পার হওয়া সাংবাদিক, দর-কষাকষিতে থাকা আইনজীবী, রেকর্ডিং শিল্পী, সন্তানদের মনোযোগের অনুভূতি শেখানো মা-বাবা: সবারই এমন একটি মুহূর্ত দরকার, যখন ডিভাইসটি কেবল <b>সেখানে নেই</b>।", "why_p3": "অনিশ্চয়তা, পরিকল্পিতভাবে।", "footer_l": "HEISENBAG — বার্লিনে হাতে তৈরি, বিশ্বজুড়ে পাঠানো হয়", "chat_fab": "নিজেরটি আঁকুন", "chat_title": "আপনার পণ্যটি বর্ণনা করুন। আমরা আঁকব।", "chat_btn": "আঁকুন", "chat_hint": "আঁকাটি বিনামূল্যে। পছন্দ হলে আমরা হাতে বানিয়ে বিশ্বজুড়ে পাঠিয়ে দিই।", "chat_ph": "একটি সুরক্ষিত গিটার কেস, গাঢ় চামড়া…", "chat_wait": "আঁকা হচ্ছে, এক মুহূর্ত…", "chat_order": "এই পণ্যটি অর্ডার করুন", "chat_fail": "আঁকা ব্যর্থ হয়েছে, আবার চেষ্টা করুন।"}, "de": {"nav_how": "So funktioniert's", "nav_learn": "Wissen", "nav_carry": "Tragen", "nav_harness": "Harness", "nav_wear": "Anziehen", "nav_space": "Raum", "nav_custom": "Maßanfertigung", "hero_h1": "Es fliegt zu viel herum. Wir sperren es aus.", "hero_p": "Handgemacht in Berlin, maßgefertigt für alle. Jedes Heisenbag Shield Stück trägt einen vollständigen Faradayschen Käfig, eingewoben in den Stoff. Für dein Handy, dein Auto, dein Studio, dein Zuhause. Nichts zu laden, nichts einzuschalten, keine App, der man vertrauen muss.", "hero_cta": "Die 24 Stücke ansehen", "how_h2": "Ein Metallkäfig, in Stoff gewoben.", "how_p": "Die Physik ist 190 Jahre alt und unschlagbar. Wir haben sie nur tragbar gemacht.", "step1": "<b>Funkwellen sind Elektrizität in der Luft.</b> Jeder Anruf, jeder GPS-Ping, jedes LTE-Paket ist ein elektrisches Feld, das die Antenne deines Handys sucht.", "step2": "<b>Ein leitfähiges Gewebe schluckt elektrische Felder.</b> Das Futter jedes Shield Produkts ist ein feines Geflecht aus Silber und Metall. Ankommende Wellen fließen darum herum, niemals hindurch.", "step3": "<b>Was nicht hineinkommt, kann dich nicht verfolgen.</b> Kein Signal erreicht das Gerät, also meldet das Gerät nichts: keinen Standort, keinen Handshake mit dem Mast, keine Daten.", "step4": "<b>Kein Akku, keine App, kein Schalter, den man vergessen kann.</b> Der Käfig wirkt durch das, was er ist, nicht durch das, was er tut. Er kann weder aktualisiert noch gehackt noch ausgeschaltet werden.", "learn_h2": "Die Physik verstehen.", "learn_p": "Drei Gedanken erklären alles, was wir machen. Wer sie einmal gesehen hat, sieht ein Handy nie wieder mit denselben Augen.", "learn1_h": "1. Wellen", "learn1_p": "Funk ist Licht, das man nicht sieht. Beides ist dasselbe: elektrische Felder, die sich wellenförmig durch den Raum bewegen. Dein Handy, dein WLAN, dein GPS-Satellit, das Sonnenlicht auf dem Tisch: eine Familie von Wellen, verschiedene Längen. Nichts Mystisches, alles messbar.", "learn2_h": "2. Licht", "learn2_p": "Ein Prisma zerlegt einen Strahl in viele Farben, weil jede Wellenlänge anders gebrochen wird. Die Wellenlänge entscheidet alles: Lange Wellen gehen durch Wände, kurze tragen Daten. 5G, LTE und Bluetooth sind nur Farben des Funks, und wie jede Farbe lassen sie sich von einer Wand aufhalten.", "learn3_h": "3. Übertragung", "learn3_p": "Dein Handy und der Mast rufen einander ständig zu, sogar während du schläfst. Über dieses Hin und Her finden Netzwerke dich, bepreisen dich und folgen dir. Hülle das Handy in einen leitfähigen Käfig, und der Ruf kommt nie an. Stille ist keine Einstellung. Sie ist Geometrie.", "carry_h2": "Tragen.", "carry_p": "Acht Taschen und Etuis, von Hand genäht. Jede schließt sich vollständig über dem Käfig, denn ein Faradayscher Käfig mit Lücke ist nur eine Tasche.", "p_holster": "Am Gürtel getragen. Das Handy mit einem Griff gezogen, mit einer Falte versiegelt.", "p_sling": "Crossbody, hoch auf der Brust. Schlüssel, Karte, Handy: dunkel.", "p_tote": "Für jeden Tag. Ein Innenfach verschluckt das Handy ganz.", "p_sleeve": "Für Tablet und Laptop. Meetings ohne Publikum.", "p_backpack": "Rolltop, 20 Liter. Ein Käfigfach, Funkloch garantiert.", "p_weekender": "Duffel in Handgepäckgröße. Grenzübertritte ohne Datenspur.", "p_keyfob": "Nimmt deinen Autoschlüssel vom Netz. Relay-Diebe hören nur Stille.", "p_wallet": "Karten und Bargeld. NFC, RFID und Skimmer bleiben draußen.", "harness_h2": "Harness.", "harness_p": "Getragen, nicht mitgeführt. Drei Harnesses, die das Handy am Körper halten und vom Netz fern, bis du es anders entscheidest.", "p_harness": "Crossbody-Harness mit Käfigtasche. Immer zur Hand, nie online.", "p_chestrig": "Volles Käfigfach vorne, Utility-Gurte. Das Rig für Studio und Bühne.", "p_wrist": "Handgelenkband mit kleinem Käfigfach. Für Schlüssel, Karten, einen ruhigen Abend.", "wear_h2": "Anziehen.", "wear_p": "Fünf Kleidungsstücke, der Käfig eingenäht in Tasche, Kapuze und Saum. Du trägst sie wie alles andere; sie wirken wie nichts sonst.", "p_hoodie": "Die Kängurutasche ist ein Funkloch. Handy rein, Welt raus.", "p_parka": "Tiefe Käfigtaschen, sturmfest außen, signalfest innen.", "p_cap": "Sechs Bahnen, eine verborgene Tasche. Die stille Cap.", "p_beanie": "Außen Strick, innen Silber. Winter, unverfolgt.", "p_scarf": "Umhüllt das Handy, das du vergessen hast auszuschalten.", "space_h2": "Raum.", "space_p": "Acht Stücke für Zuhause, Büro und Reise. Vom Vorhang, der ein Fenster verdunkelt, bis zum Zelt, in dem ein Gespräch ein Gespräch bleibt.", "p_tent": "Pop-up-Privatraum für zwei. Nichts rein, nichts raus.", "p_curtain": "Eine Bahn, volle Länge. Das Fenster hört auf zu lauschen.", "p_canopy": "Betthimmel fürs Kinderbett. Der kleinste Schläfer, die stillste Luft.", "p_blanket": "Eine Decke fürs Sofa. Geräte darunter sind verschwunden.", "p_cone": "Tischkegel für Meetings. Handys rein, Köpfe anwesend.", "p_sleepbox": "Box für den Nachttisch. Das Handy schläft vor dir.", "p_keybox": "Box für den Eingang. Jeder Schlüssel im Haus, vom Netz.", "p_router": "Eine Glocke für das WLAN. Nachtmodus, durchgesetzt von der Physik.", "custom_h2": "Maßanfertigung. Wir schirmen alles ab.", "custom_p": "Jedes Stück ist handgemacht und für dich maßgefertigt. Beschreibe, was still sein soll, wir zeichnen es in unserem Stil direkt hier im Chat, und sobald du die Zeichnung liebst, nähen echte Menschen es und versenden es weltweit.", "p_carcover": "Dein Auto verschwindet aus jedem Netz, während es schläft.", "p_studio": "Tonstudios, Labore, Besprechungsräume. Wände, die den Atem anhalten.", "on_request1": "auf Anfrage", "p_research": "Gemessene Dämpfung für Labore, Kliniken und alle, die Gewissheit brauchen.", "on_request2": "auf Anfrage", "p_anything": "Vorhänge, Hüllen, Kleidung, Gehäuse. Was du beschreiben kannst, können wir abschirmen.", "on_request3": "auf Anfrage", "custom_cta": "Dein eigenes Stück zeichnen", "why_h2": "Jeder ist erreichbar. Fast niemand entscheidet, wann.", "why_p1": "Dein Handy spricht rund um die Uhr mit Masten, Satelliten, Beacons und Apps. Es tut das <b>in deiner Tasche, auf deinem Nachttisch, in deinen Meetings</b>. Der Flugmodus ist ein Versprechen derselben Unternehmen, die deinen Standort zu Geld machen. Ein Faradayscher Käfig ist kein Versprechen. Er ist Physik.", "why_p2": "Jedes Shield Stück ist handgemacht, gefüttert mit versilbertem Polyamidgewebe, gewebt in Deutschland, mit einer Dämpfung von 60 dB und mehr von 200 MHz bis 14 GHz: 5G, LTE, GPS, wifi, Bluetooth, NFC. Journalisten auf Grenzübertritten, Anwälte in Verhandlungen, Musiker im Studio, Eltern, die Kindern zeigen, wie sich Aufmerksamkeit anfühlt: Sie alle brauchen einen Moment, in dem das Gerät einfach <b>nicht da ist</b>.", "why_p3": "Unschärfe, mit Absicht.", "footer_l": "HEISENBAG — Handgemacht in Berlin, weltweiter Versand", "chat_fab": "Zeichne deins", "chat_title": "Beschreibe dein Stück. Wir zeichnen es.", "chat_btn": "Zeichnen", "chat_hint": "Die Zeichnung ist kostenlos. Wenn du sie liebst, fertigen wir sie von Hand und versenden weltweit.", "chat_ph": "Eine abgeschirmte Gitarrentasche, dunkles Leder…", "chat_wait": "Wird gezeichnet, einen Moment…", "chat_order": "Dieses Stück bestellen", "chat_fail": "Zeichnen fehlgeschlagen, bitte erneut versuchen."}, "es": {"nav_how": "Cómo funciona", "nav_learn": "Aprende", "nav_carry": "Llevar", "nav_harness": "Arneses", "nav_wear": "Vestir", "nav_space": "Espacio", "nav_custom": "A medida", "hero_h1": "Hay demasiado volando por el aire. Nosotros lo dejamos fuera.", "hero_p": "Hecho a mano en Berlín, a medida para todos. Cada pieza Heisenbag Shield lleva una jaula de Faraday completa tejida en la tela. Para tu teléfono, tu coche, tu estudio, tu hogar. Nada que cargar, nada que encender, ninguna app en la que confiar.", "hero_cta": "Ver las 24 piezas", "how_h2": "Una jaula de metal, tejida en tela.", "how_p": "La física tiene 190 años y es imbatible. Nosotros solo la hicimos ponible.", "step1": "<b>Las ondas de radio son electricidad en el aire.</b> Cada llamada, cada ping de GPS, cada paquete LTE es un campo eléctrico que busca la antena de tu teléfono.", "step2": "<b>Una malla conductora devora los campos eléctricos.</b> El forro de cada producto Shield es un fino tejido de plata y metal. Las ondas que llegan fluyen a su alrededor, nunca a través.", "step3": "<b>Lo que no puede entrar no puede rastrearte.</b> Ninguna señal llega al dispositivo, así que el dispositivo no informa de nada: ni ubicación, ni saludo con la antena, ni datos.", "step4": "<b>Sin batería, sin app, sin interruptor que olvidar.</b> La jaula funciona por lo que es, no por lo que hace. No se puede actualizar, hackear ni apagar.", "learn_h2": "Aprende la física.", "learn_p": "Tres ideas explican todo lo que hacemos. Una vez que las veas, nunca volverás a mirar un teléfono de la misma manera.", "learn1_h": "1. Ondas", "learn1_p": "La radio es luz que no puedes ver. Ambas son lo mismo: campos eléctricos que ondulan por el espacio. Tu teléfono, tu wifi, tu satélite GPS, la luz del sol sobre la mesa: una misma familia de ondas, distintas longitudes. Nada místico, todo medible.", "learn2_h": "2. Luz", "learn2_p": "Un prisma divide un haz en muchos colores porque cada longitud de onda se curva de forma distinta. La longitud de onda lo decide todo: las ondas largas atraviesan paredes, las cortas transportan datos. 5G, LTE y Bluetooth son solo colores de la radio, y como todo color, una pared puede detenerlos.", "learn3_h": "3. Transmisión", "learn3_p": "Tu teléfono y la antena se gritan constantemente, incluso mientras duermes. Con ese grito de ida y vuelta las redes te encuentran, te ponen precio y te siguen. Envuelve el teléfono en una jaula conductora y el grito nunca llega. El silencio no es un ajuste. Es geometría.", "carry_h2": "Llevar.", "carry_p": "Ocho bolsos y fundas, cosidos a mano. Cada uno se cierra por completo sobre la jaula, porque una jaula de Faraday con una abertura es solo un bolso.", "p_holster": "Se lleva en el cinturón. El teléfono sale en un gesto y se sella en un pliegue.", "p_sling": "Cruzado, alto sobre el pecho. Llaves, tarjeta, teléfono: a oscuras.", "p_tote": "El bolso de cada día. Un bolsillo interior se traga el teléfono entero.", "p_sleeve": "Para tableta y portátil. Reuniones sin público.", "p_backpack": "Roll-top, 20 litros. Un bolsillo jaula, zona muerta garantizada.", "p_weekender": "Bolsa de viaje tamaño cabina. Cruzar fronteras sin rastro de datos.", "p_keyfob": "Saca la llave de tu coche del aire. Los ladrones por relé solo encuentran silencio.", "p_wallet": "Tarjetas y efectivo. NFC, RFID y skimmers se quedan fuera.", "harness_h2": "Arneses.", "harness_p": "Puestos, no llevados. Tres arneses que mantienen el teléfono pegado a tu cuerpo y fuera del aire hasta que tú decidas lo contrario.", "p_harness": "Arnés cruzado con funda jaula. Siempre a mano, nunca en línea.", "p_chestrig": "Gran bolsillo jaula frontal, correas utilitarias. El rig para estudio y escenario.", "p_wrist": "Correa de muñeca con mini bolsillo jaula. Para llaves, tarjetas, una noche tranquila.", "wear_h2": "Vestir.", "wear_p": "Cinco prendas con la jaula cosida en bolsillo, capucha y dobladillo. Las llevas como cualquier otra cosa; funcionan como ninguna otra.", "p_hoodie": "El bolsillo canguro es una zona muerta. Teléfono dentro, mundo fuera.", "p_parka": "Bolsillos jaula profundos, a prueba de tormentas por fuera, a prueba de señales por dentro.", "p_cap": "Seis paneles, un bolsillo oculto. La gorra silenciosa.", "p_beanie": "Punto por fuera, plata por dentro. El invierno, sin rastreo.", "p_scarf": "Envuelve el teléfono que olvidaste apagar.", "space_h2": "Espacio.", "space_p": "Ocho piezas para casa, oficina y viaje. Desde una cortina que oscurece una ventana hasta una tienda donde una conversación sigue siendo una conversación.", "p_tent": "Sala privada desplegable para dos. Nada entra, nada sale.", "p_curtain": "Un panel, de altura completa. La ventana deja de escuchar.", "p_canopy": "Dosel para cuna. El durmiente más pequeño, el aire más tranquilo.", "p_blanket": "Una manta para el sofá. Los dispositivos debajo desaparecen.", "p_cone": "Cono de mesa para reuniones. Teléfonos dentro, mentes presentes.", "p_sleepbox": "Caja de mesilla. El teléfono se duerme antes que tú.", "p_keybox": "Caja de entrada. Todas las llaves de la casa, fuera del aire.", "p_router": "Una campana para el wifi. Modo nocturno, impuesto por la física.", "custom_h2": "A medida. Blindamos cualquier cosa.", "custom_p": "Cada pieza está hecha a mano y a medida para ti. Describe lo que debe guardar silencio, lo dibujamos en nuestro estilo aquí mismo en el chat y, cuando el dibujo te enamore, personas reales lo cosen y lo envían a todo el mundo.", "p_carcover": "Tu coche desaparece de todas las redes mientras duerme.", "p_studio": "Estudios de grabación, laboratorios, salas de reuniones. Paredes que contienen la respiración.", "on_request1": "bajo pedido", "p_research": "Atenuación medida para laboratorios, clínicas y cualquiera que necesite certeza.", "on_request2": "bajo pedido", "p_anything": "Cortinas, fundas, prendas, recintos. Si puedes describirlo, podemos blindarlo.", "on_request3": "bajo pedido", "custom_cta": "Dibuja tu propia pieza", "why_h2": "Todos somos localizables. Casi nadie elige cuándo.", "why_p1": "Tu teléfono habla con antenas, satélites, balizas y apps a todas horas. Lo hace <b>en tu bolsillo, en tu mesilla de noche, en tus reuniones</b>. El modo avión es una promesa de las mismas empresas que monetizan tu ubicación. Una jaula de Faraday no es una promesa. Es física.", "why_p2": "Cada pieza Shield está hecha a mano, forrada con tejido de poliamida plateada tejido en Alemania, con una atenuación de 60 dB o más de 200 MHz a 14 GHz: 5G, LTE, GPS, wifi, Bluetooth, NFC. Periodistas que cruzan fronteras, abogados en negociaciones, artistas en el estudio, padres que enseñan a sus hijos lo que se siente al prestar atención: todos necesitan un momento en el que el dispositivo simplemente <b>no está</b>.", "why_p3": "Incertidumbre, por diseño.", "footer_l": "HEISENBAG — Hecho a mano en Berlín, enviado a todo el mundo", "chat_fab": "Dibuja el tuyo", "chat_title": "Describe tu pieza. Nosotros la dibujamos.", "chat_btn": "Dibujar", "chat_hint": "El dibujo es gratis. Si te enamora, lo hacemos a mano y lo enviamos a todo el mundo.", "chat_ph": "Un estuche de guitarra blindado, cuero oscuro…", "chat_wait": "Dibujando, un momento…", "chat_order": "Pedir esta pieza", "chat_fail": "El dibujo falló, inténtalo de nuevo."}, "fa": {"nav_how": "چگونه کار می‌کند", "nav_learn": "بیاموزید", "nav_carry": "همراه", "nav_harness": "بند", "nav_wear": "پوشیدنی", "nav_space": "فضا", "nav_custom": "سفارشی", "hero_h1": "در هوا چیزهای زیادی در پروازند. ما آن‌ها را بیرون نگه می‌داریم.", "hero_p": "دست‌ساز در برلین، سفارشی برای همه. هر قطعهٔ Heisenbag Shield یک قفس فارادی کامل را در بافت پارچه‌اش دارد. برای گوشی‌تان، خودروتان، استودیوتان، خانه‌تان. نه نیازی به شارژ، نه نیازی به روشن کردن، نه اپی که باید به آن اعتماد کنید.", "hero_cta": "دیدن هر 24 قطعه", "how_h2": "قفسی فلزی، بافته در پارچه.", "how_p": "این فیزیک 190 سال قدمت دارد و شکست‌ناپذیر است. ما فقط آن را پوشیدنی کردیم.", "step1": "<b>امواج رادیویی، برقِ جاری در هواست.</b> هر تماس، هر پینگ GPS، هر بستهٔ LTE میدانی الکتریکی است که در جست‌وجوی آنتن گوشی شماست.", "step2": "<b>توری رسانا میدان‌های الکتریکی را می‌بلعد.</b> آستر هر محصول Shield بافتی ظریف از نقره و فلز است. امواجِ رسیده از کنارش می‌گذرند، هرگز از میانش نه.", "step3": "<b>آنچه نتواند وارد شود، نمی‌تواند ردیابی‌تان کند.</b> هیچ سیگنالی به دستگاه نمی‌رسد، پس دستگاه چیزی گزارش نمی‌دهد: نه موقعیت، نه دست‌دادن با دکل، نه داده.", "step4": "<b>نه باتری، نه اپ، نه کلید خاموشی که فراموشش کنید.</b> این قفس به خاطر آنچه هست کار می‌کند، نه آنچه انجام می‌دهد. نه به‌روزرسانی می‌شود، نه هک، نه خاموش.", "learn_h2": "فیزیک را بیاموزید.", "learn_p": "سه ایده همه چیزهایی را که می‌سازیم توضیح می‌دهند. وقتی آن‌ها را ببینید، دیگر هرگز به گوشی مثل قبل نگاه نخواهید کرد.", "learn1_h": "1. امواج", "learn1_p": "رادیو نوری است که نمی‌بینید. هر دو یک چیزند: میدان‌های الکتریکی که در فضا موج برمی‌دارند. گوشی‌تان، wifi شما، ماهوارهٔ GPS شما، نور خورشید روی میز: یک خانوادهٔ موج، با طول‌های متفاوت. هیچ رازی در کار نیست، همه‌چیز قابل اندازه‌گیری است.", "learn2_h": "2. نور", "learn2_p": "منشور یک پرتو را به رنگ‌های بسیار می‌شکند، چون هر طول موج به شکلی متفاوت خم می‌شود. طول موج همه‌چیز را تعیین می‌کند: امواج بلند از دیوارها می‌گذرند، امواج کوتاه داده حمل می‌کنند. 5G، LTE و Bluetooth تنها رنگ‌هایی از رادیو هستند، و مثل هر رنگی، یک دیوار می‌تواند متوقفشان کند.", "learn3_h": "3. انتقال", "learn3_p": "گوشی شما و دکل بی‌وقفه یکدیگر را صدا می‌زنند، حتی وقتی خوابید. همین فریاد دوسویه است که شبکه‌ها با آن پیدایتان می‌کنند، برایتان قیمت می‌گذارند و دنبالتان می‌کنند. گوشی را در قفسی رسانا بپیچید و آن فریاد هرگز نمی‌رسد. سکوت یک تنظیم نیست. هندسه است.", "carry_h2": "همراه.", "carry_p": "هشت کیف و کیسه، دوخته با دست. هر کدام کاملاً روی قفس بسته می‌شود، چون قفس فارادی‌ای که شکاف داشته باشد، فقط یک کیف است.", "p_holster": "روی کمربند. گوشی با یک حرکت بیرون می‌آید، با یک تا مهر و موم می‌شود.", "p_sling": "دوشی‌ضربدری، بالا روی سینه. کلید، کارت، گوشی: در تاریکی.", "p_tote": "همراه هر روز. یک جیب درونی گوشی را یکجا می‌بلعد.", "p_sleeve": "برای تبلت و لپ‌تاپ. جلسه‌هایی بی‌تماشاگر.", "p_backpack": "درِ لوله‌ای، 20 لیتر. یک جیب قفسی، منطقهٔ مرده تضمینی.", "p_weekender": "ساک هم‌اندازهٔ کابین. عبور از مرزها بی‌ردپای داده.", "p_keyfob": "کلید خودروتان را از هوا بیرون می‌کشد. دزدان رله فقط سکوت می‌گیرند.", "p_wallet": "کارت و پول نقد. NFC، RFID و دستگاه‌های کپی‌برداری، همه پشت در.", "harness_h2": "بند.", "harness_p": "پوشیدنی، نه حمل‌کردنی. سه بند که گوشی را روی بدنتان و دور از امواج نگه می‌دارند، تا وقتی خودتان جور دیگری تصمیم بگیرید.", "p_harness": "بند ضربدری با کیسهٔ قفسی. همیشه دم دست، هرگز آنلاین.", "p_chestrig": "جیب قفسی تمام‌جلو، تسمه‌های کاربردی. تجهیزات استودیو و صحنه.", "p_wrist": "مچ‌بند با جیب قفسی کوچک. برای کلیدها، کارت‌ها، یک شب آرام.", "wear_h2": "پوشیدنی.", "wear_p": "پنج پوشاک که قفس در جیب، کلاه و لبه‌شان دوخته شده. آن‌ها را مثل هر چیز دیگری می‌پوشید؛ اما مثل هیچ چیز دیگری کار می‌کنند.", "p_hoodie": "جیب کانگورویی یک منطقهٔ مرده است. گوشی داخل، دنیا بیرون.", "p_parka": "جیب‌های قفسی عمیق، بیرون ضد طوفان، درون ضد سیگنال.", "p_cap": "شش ترک، یک جیب پنهان. کلاه آرام.", "p_beanie": "بافتنی بیرون، نقره درون. زمستان، بی‌ردیابی.", "p_scarf": "گوشی‌ای را که فراموش کردید خاموش کنید، در بر می‌گیرد.", "space_h2": "فضا.", "space_p": "هشت قطعه برای خانه، دفتر و سفر. از پرده‌ای که پنجره را کاملاً تاریک می‌کند تا چادری که در آن گفت‌وگو، گفت‌وگو می‌ماند.", "p_tent": "اتاق حریم خصوصی بازشونده برای دو نفر. هیچ چیز داخل نمی‌شود، هیچ چیز بیرون نمی‌رود.", "p_curtain": "یک لت، تمام‌قد. پنجره دیگر گوش نمی‌دهد.", "p_canopy": "سایه‌بان گهواره. کوچک‌ترین خفته، آرام‌ترین هوا.", "p_blanket": "روانداز مبل. دستگاه‌های زیر آن ناپدید می‌شوند.", "p_cone": "مخروط رومیزی برای جلسه‌ها. گوشی‌ها داخل، ذهن‌ها حاضر.", "p_sleepbox": "جعبهٔ کنار تخت. گوشی پیش از شما به خواب می‌رود.", "p_keybox": "جعبهٔ ورودی. همهٔ کلیدهای خانه، دور از امواج.", "p_router": "سرپوشی برای wifi. حالت شب، به حکم فیزیک.", "custom_h2": "سفارشی. ما هر چیزی را محافظت می‌کنیم.", "custom_p": "هر قطعه دست‌ساز و سفارشی برای شماست. بگویید چه چیزی باید ساکت شود، ما همین‌جا در گفت‌وگو آن را به سبک خودمان طراحی می‌کنیم، و وقتی عاشق طرح شدید، آدم‌هایی واقعی آن را می‌دوزند و به سراسر جهان می‌فرستند.", "p_carcover": "خودروی شما هنگام خواب از همهٔ شبکه‌ها ناپدید می‌شود.", "p_studio": "استودیوهای ضبط، آزمایشگاه‌ها، اتاق‌های جلسه. دیوارهایی که نفسشان را حبس می‌کنند.", "on_request1": "بنا به درخواست", "p_research": "تضعیف اندازه‌گیری‌شده برای آزمایشگاه‌ها، درمانگاه‌ها و هر کسی که به قطعیت نیاز دارد.", "on_request2": "بنا به درخواست", "p_anything": "پرده، روکش، پوشاک، محفظه. اگر بتوانید توصیفش کنید، ما می‌توانیم محافظتش کنیم.", "on_request3": "بنا به درخواست", "custom_cta": "قطعهٔ خودتان را طراحی کنید", "why_h2": "همه در دسترس‌اند. تقریباً هیچ‌کس انتخاب نمی‌کند کِی.", "why_p1": "گوشی شما شبانه‌روز با دکل‌ها، ماهواره‌ها، بیکن‌ها و اپ‌ها حرف می‌زند. این کار را می‌کند <b>در جیبتان، روی پاتختی‌تان، در جلسه‌هایتان</b>. حالت پرواز وعده‌ای است از همان شرکت‌هایی که از موقعیت شما پول درمی‌آورند. قفس فارادی وعده نیست. فیزیک است.", "why_p2": "هر قطعهٔ Shield دست‌ساز است و با پارچهٔ پلی‌آمید نقره‌اندود بافته‌شده در آلمان آستر شده، که از 200 MHz تا 14 GHz دست‌کم 60 dB تضعیف ایجاد می‌کند: 5G، LTE، GPS، wifi، Bluetooth، NFC. روزنامه‌نگارانی که از مرز می‌گذرند، وکلایی در میانهٔ مذاکره، هنرمندان ضبط، والدینی که به کودکانشان حسِ توجه را می‌آموزند: همه به لحظه‌ای نیاز دارند که دستگاه به‌سادگی <b>آنجا نباشد</b>.", "why_p3": "عدم قطعیت، از روی طراحی.", "footer_l": "HEISENBAG — دست‌ساز در برلین، ارسال به سراسر جهان", "chat_fab": "طرح خودتان", "chat_title": "قطعه‌تان را توصیف کنید. ما طراحی‌اش می‌کنیم.", "chat_btn": "طراحی کن", "chat_hint": "طراحی رایگان است. اگر دوستش داشتید، آن را با دست می‌سازیم و به سراسر جهان می‌فرستیم.", "chat_ph": "یک جعبهٔ گیتار محافظ‌دار، چرم تیره…", "chat_wait": "در حال طراحی، لحظه‌ای…", "chat_order": "سفارش این قطعه", "chat_fail": "طراحی ناموفق بود، دوباره تلاش کنید."}, "fr": {"nav_how": "Fonctionnement", "nav_learn": "Comprendre", "nav_carry": "Porter", "nav_harness": "Harnais", "nav_wear": "Vêtir", "nav_space": "Espace", "nav_custom": "Sur mesure", "hero_h1": "Trop de choses circulent dans l'air. Nous les tenons à distance.", "hero_p": "Fait main à Berlin, sur mesure pour chacun. Chaque pièce Heisenbag Shield renferme une cage de Faraday complète, tissée dans l'étoffe. Pour votre téléphone, votre voiture, votre studio, votre maison. Rien à recharger, rien à allumer, aucune app à qui faire confiance.", "hero_cta": "Voir les 24 pièces", "how_h2": "Une cage de métal, tissée dans le tissu.", "how_p": "La physique a 190 ans et reste imbattable. Nous l'avons simplement rendue portable.", "step1": "<b>Les ondes radio sont de l'électricité dans l'air.</b> Chaque appel, chaque signal GPS, chaque paquet LTE est un champ électrique qui cherche l'antenne de votre téléphone.", "step2": "<b>Un maillage conducteur absorbe les champs électriques.</b> La doublure de chaque produit Shield est un fin tissage d'argent et de métal. Les ondes qui arrivent glissent autour, jamais à travers.", "step3": "<b>Ce qui ne peut pas entrer ne peut pas vous suivre.</b> Aucun signal n'atteint l'appareil, alors l'appareil ne transmet rien : ni position, ni échange avec l'antenne, ni données.", "step4": "<b>Pas de batterie, pas d'app, pas d'interrupteur à oublier.</b> La cage fonctionne par ce qu'elle est, non par ce qu'elle fait. Elle ne peut être ni mise à jour, ni piratée, ni éteinte.", "learn_h2": "Comprendre la physique.", "learn_p": "Trois idées expliquent tout ce que nous fabriquons. Une fois que vous les aurez vues, vous ne regarderez plus jamais un téléphone de la même façon.", "learn1_h": "1. Les ondes", "learn1_p": "La radio est une lumière invisible. Les deux sont une seule et même chose : des champs électriques qui ondulent dans l'espace. Votre téléphone, votre wifi, votre satellite GPS, la lumière du soleil sur la table : une même famille d'ondes, des longueurs différentes. Rien de mystique, tout est mesurable.", "learn2_h": "2. La lumière", "learn2_p": "Un prisme divise un faisceau en de nombreuses couleurs, car chaque longueur d'onde se courbe différemment. La longueur d'onde décide de tout : les ondes longues traversent les murs, les courtes transportent les données. La 5G, le LTE et le Bluetooth ne sont que des couleurs de la radio, et comme toute couleur, un mur peut les arrêter.", "learn3_h": "3. La transmission", "learn3_p": "Votre téléphone et l'antenne se crient dessus sans cesse, même pendant votre sommeil. C'est par ce dialogue que les réseaux vous trouvent, vous évaluent et vous suivent. Enveloppez le téléphone dans une cage conductrice, et le cri n'arrive jamais. Le silence n'est pas un réglage. C'est de la géométrie.", "carry_h2": "Porter.", "carry_p": "Huit sacs et pochettes, cousus à la main. Chacun se referme entièrement sur la cage, car une cage de Faraday avec une ouverture n'est qu'un sac.", "p_holster": "Porté à la ceinture. Le téléphone sorti d'un geste, scellé d'un pli.", "p_sling": "En bandoulière, haut sur la poitrine. Clés, carte, téléphone : dans le noir.", "p_tote": "Le sac du quotidien. Une poche intérieure avale le téléphone tout entier.", "p_sleeve": "Pour tablette et ordinateur portable. Des réunions sans public.", "p_backpack": "Roll-top, 20 litres. Une poche-cage, zone blanche garantie.", "p_weekender": "Sac de voyage au format cabine. Passer les frontières sans laisser de traces.", "p_keyfob": "Coupe votre clé de voiture des ondes. Les voleurs par relais n'entendent que le silence.", "p_wallet": "Cartes et billets. NFC, RFID et skimmers restent à la porte.", "harness_h2": "Harnais.", "harness_p": "Porté sur soi, pas transporté. Trois harnais qui gardent le téléphone contre votre corps et hors des ondes, jusqu'à ce que vous en décidiez autrement.", "p_harness": "Harnais en bandoulière avec pochette-cage. Toujours à portée de main, jamais en ligne.", "p_chestrig": "Grande poche-cage frontale, sangles utilitaires. Le rig du studio et de la scène.", "p_wrist": "Dragonne avec mini poche-cage. Pour les clés, les cartes, une soirée tranquille.", "wear_h2": "Vêtir.", "wear_p": "Cinq vêtements, la cage cousue dans la poche, la capuche et l'ourlet. Vous les portez comme n'importe quoi d'autre ; ils agissent comme rien d'autre.", "p_hoodie": "La poche kangourou est une zone blanche. Le téléphone dedans, le monde dehors.", "p_parka": "Poches-cages profondes, à l'épreuve des tempêtes dehors, des signaux dedans.", "p_cap": "Six panneaux, une poche cachée. La casquette silencieuse.", "p_beanie": "Tricot dehors, argent dedans. L'hiver, sans traçage.", "p_scarf": "Enveloppe le téléphone que vous avez oublié d'éteindre.", "space_h2": "Espace.", "space_p": "Huit pièces pour la maison, le bureau et le voyage. Du rideau qui occulte une fenêtre à la tente où une conversation reste une conversation.", "p_tent": "Pièce privée instantanée pour deux. Rien n'entre, rien ne sort.", "p_curtain": "Un panneau, pleine hauteur. La fenêtre cesse d'écouter.", "p_canopy": "Ciel de berceau. Le plus petit dormeur, l'air le plus calme.", "p_blanket": "Un plaid pour le canapé. Les appareils glissés dessous disparaissent.", "p_cone": "Cône de table pour les réunions. Téléphones dedans, esprits présents.", "p_sleepbox": "Boîte de chevet. Le téléphone s'endort avant vous.", "p_keybox": "Boîte d'entrée. Toutes les clés de la maison, hors des ondes.", "p_router": "Une cloche pour le wifi. Le mode nuit, imposé par la physique.", "custom_h2": "Sur mesure. Nous blindons tout.", "custom_p": "Chaque pièce est faite main et sur mesure pour vous. Décrivez ce qui doit se taire, nous le dessinons dans notre style ici même dans le chat, et dès que le dessin vous plaît, de vraies personnes le cousent et l'expédient dans le monde entier.", "p_carcover": "Votre voiture disparaît de tous les réseaux pendant qu'elle dort.", "p_studio": "Studios d'enregistrement, laboratoires, salles de réunion. Des murs qui retiennent leur souffle.", "on_request1": "sur demande", "p_research": "Atténuation mesurée pour les laboratoires, les cliniques et tous ceux qui ont besoin de certitude.", "on_request2": "sur demande", "p_anything": "Rideaux, housses, vêtements, enceintes. Si vous pouvez le décrire, nous pouvons le blinder.", "on_request3": "sur demande", "custom_cta": "Dessinez votre pièce", "why_h2": "Tout le monde est joignable. Presque personne ne choisit quand.", "why_p1": "Votre téléphone parle aux antennes, aux satellites, aux balises et aux apps jour et nuit. Il le fait <b>dans votre poche, sur votre table de nuit, pendant vos réunions</b>. Le mode avion est une promesse faite par les mêmes entreprises qui monétisent votre position. Une cage de Faraday n'est pas une promesse. C'est de la physique.", "why_p2": "Chaque pièce Shield est faite main, doublée d'un tissu en polyamide argenté tissé en Allemagne, avec une atténuation de 60 dB et plus de 200 MHz à 14 GHz : 5G, LTE, GPS, wifi, Bluetooth, NFC. Journalistes qui passent des frontières, avocats en négociation, artistes en studio, parents qui apprennent à leurs enfants ce qu'est l'attention : tous ont besoin d'un moment où l'appareil n'est tout simplement <b>pas là</b>.", "why_p3": "L'incertitude, par conception.", "footer_l": "HEISENBAG — Fait main à Berlin, expédié dans le monde entier", "chat_fab": "Dessinez le vôtre", "chat_title": "Décrivez votre pièce. Nous la dessinons.", "chat_btn": "Dessiner", "chat_hint": "Le dessin est gratuit. S'il vous plaît, nous le fabriquons à la main et l'expédions dans le monde entier.", "chat_ph": "Un étui à guitare blindé, cuir sombre…", "chat_wait": "Dessin en cours, un instant…", "chat_order": "Commander cette pièce", "chat_fail": "Le dessin a échoué, réessayez."}, "hi": {"nav_how": "यह कैसे काम करता है", "nav_learn": "जानें", "nav_carry": "साथ रखें", "nav_harness": "हार्नेस", "nav_wear": "पहनें", "nav_space": "स्पेस", "nav_custom": "कस्टम", "hero_h1": "हवा में बहुत कुछ उड़ रहा है। हम उसे बाहर रखते हैं।", "hero_p": "बर्लिन में हाथ से बना, हर किसी के लिए नाप से बना। हर Heisenbag Shield पीस के कपड़े में एक पूरा फैराडे केज बुना हुआ है। आपके फ़ोन के लिए, आपकी कार के लिए, आपके स्टूडियो के लिए, आपके घर के लिए। न चार्ज करना, न चालू करना, न किसी ऐप पर भरोसा करना।", "hero_cta": "सभी 24 पीस देखें", "how_h2": "धातु का एक पिंजरा, कपड़े में बुना हुआ।", "how_p": "यह भौतिकी 190 साल पुरानी है और अजेय है। हमने बस इसे पहनने लायक बना दिया।", "step1": "<b>रेडियो तरंगें हवा में बहती बिजली हैं।</b> हर कॉल, हर GPS पिंग, हर LTE पैकेट एक विद्युत क्षेत्र है जो आपके फ़ोन का एंटीना ढूँढ रहा है।", "step2": "<b>सुचालक जाली विद्युत क्षेत्रों को निगल जाती है।</b> हर Shield उत्पाद का अस्तर चाँदी और धातु की बारीक बुनाई है। आती हुई तरंगें इसके चारों ओर बह जाती हैं, कभी इसके पार नहीं।", "step3": "<b>जो अंदर नहीं आ सकता, वह आपको ट्रैक नहीं कर सकता।</b> कोई सिग्नल डिवाइस तक नहीं पहुँचता, इसलिए डिवाइस कुछ भी रिपोर्ट नहीं करता: न लोकेशन, न टावर से हैंडशेक, न डेटा।", "step4": "<b>न बैटरी, न ऐप, न कोई बंद करने का स्विच जिसे आप भूल जाएँ।</b> यह पिंजरा इसलिए काम करता है कि यह क्या है, इसलिए नहीं कि यह क्या करता है। इसे न अपडेट किया जा सकता है, न हैक, न बंद।", "learn_h2": "भौतिकी को समझें।", "learn_p": "तीन विचार हमारी बनाई हर चीज़ को समझा देते हैं। एक बार इन्हें देख लिया, तो आप फ़ोन को फिर कभी पहले की तरह नहीं देखेंगे।", "learn1_h": "1. तरंगें", "learn1_p": "रेडियो वह प्रकाश है जिसे आप देख नहीं सकते। दोनों एक ही चीज़ हैं: अंतरिक्ष में लहराते विद्युत क्षेत्र। आपका फ़ोन, आपका wifi, आपका GPS उपग्रह, मेज़ पर पड़ी धूप: तरंगों का एक ही परिवार, बस अलग-अलग लंबाई। कुछ भी रहस्यमय नहीं, सब कुछ मापा जा सकता है।", "learn2_h": "2. प्रकाश", "learn2_p": "प्रिज़्म एक किरण को कई रंगों में बाँट देता है, क्योंकि हर तरंगदैर्ध्य अलग ढंग से मुड़ता है। तरंगदैर्ध्य ही सब कुछ तय करता है: लंबी तरंगें दीवारों के पार निकल जाती हैं, छोटी तरंगें डेटा ढोती हैं। 5G, LTE और Bluetooth रेडियो के बस अलग-अलग रंग हैं, और हर रंग की तरह, एक दीवार उन्हें रोक सकती है।", "learn3_h": "3. संचरण", "learn3_p": "आपका फ़ोन और टावर लगातार एक-दूसरे को पुकारते रहते हैं, तब भी जब आप सो रहे होते हैं। इसी दोतरफ़ा पुकार से नेटवर्क आपको ढूँढते हैं, आपकी क़ीमत लगाते हैं और आपका पीछा करते हैं। फ़ोन को एक सुचालक पिंजरे में लपेट दीजिए, और वह पुकार कभी नहीं पहुँचती। ख़ामोशी कोई सेटिंग नहीं है। यह ज्यामिति है।", "carry_h2": "साथ रखें।", "carry_p": "आठ बैग और पाउच, हाथ से सिले हुए। हर एक केज के ऊपर पूरी तरह बंद होता है, क्योंकि जिस फैराडे केज में दरार हो, वह बस एक बैग है।", "p_holster": "बेल्ट पर पहना जाता है। एक हरकत में फ़ोन बाहर, एक मोड़ में सील।", "p_sling": "क्रॉसबॉडी, सीने पर ऊँचा। चाबियाँ, कार्ड, फ़ोन: सब अंधेरे में।", "p_tote": "रोज़ का साथी। अंदर की एक जेब फ़ोन को पूरा निगल लेती है।", "p_sleeve": "टैबलेट और लैपटॉप के लिए। मीटिंग, बिना किसी श्रोता के।", "p_backpack": "रोल-टॉप, 20 लीटर। एक केज जेब, डेड ज़ोन की गारंटी।", "p_weekender": "केबिन साइज़ डफ़ल। सरहदें पार करें, बिना किसी डेटा के निशान के।", "p_keyfob": "आपकी कार की चाबी को हवा से हटा देता है। रिले चोरों को मिलती है बस ख़ामोशी।", "p_wallet": "कार्ड और नकदी। NFC, RFID और स्किमर, सब बाहर।", "harness_h2": "हार्नेस।", "harness_p": "पहना जाता है, उठाया नहीं जाता। तीन हार्नेस जो फ़ोन को आपके शरीर पर और हवा से दूर रखते हैं, जब तक आप कुछ और तय न करें।", "p_harness": "केज वाले पाउच के साथ क्रॉसबॉडी हार्नेस। हमेशा हाथ के पास, कभी ऑनलाइन नहीं।", "p_chestrig": "पूरे सामने की केज जेब, यूटिलिटी स्ट्रैप्स। स्टूडियो और मंच का रिग।", "p_wrist": "मिनी केज जेब वाला रिस्ट स्ट्रैप। चाबियों, कार्डों और एक सुकून भरी शाम के लिए।", "wear_h2": "पहनें।", "wear_p": "पाँच परिधान, जिनकी जेब, हुड और किनारे में केज सिला हुआ है। आप इन्हें किसी भी और कपड़े की तरह पहनते हैं; ये किसी और चीज़ की तरह काम नहीं करते।", "p_hoodie": "कंगारू जेब एक डेड ज़ोन है। फ़ोन अंदर, दुनिया बाहर।", "p_parka": "गहरी केज जेबें, बाहर से तूफ़ान-रोधी, अंदर से सिग्नल-रोधी।", "p_cap": "छह पैनल, एक छिपी जेब। ख़ामोश टोपी।", "p_beanie": "बाहर बुनाई, अंदर चाँदी। सर्दी, बिना ट्रैकिंग के।", "p_scarf": "उस फ़ोन को लपेट लेता है जिसे आप बंद करना भूल गए।", "space_h2": "स्पेस।", "space_p": "घर, दफ़्तर और सफ़र के लिए आठ पीस। खिड़की को पूरी तरह ढक देने वाले पर्दे से लेकर एक ऐसे टेंट तक जहाँ बातचीत बस बातचीत ही रहती है।", "p_tent": "दो लोगों के लिए पॉप-अप प्राइवेसी रूम। न कुछ अंदर, न कुछ बाहर।", "p_curtain": "एक पैनल, पूरी लंबाई। खिड़की सुनना बंद कर देती है।", "p_canopy": "पालने की छतरी। सबसे नन्हा सोने वाला, सबसे शांत हवा।", "p_blanket": "सोफ़े के लिए एक थ्रो। इसके नीचे रखे डिवाइस ग़ायब।", "p_cone": "मीटिंग के लिए टेबलटॉप कोन। फ़ोन अंदर, मन मौजूद।", "p_sleepbox": "बेडसाइड बॉक्स। फ़ोन आपसे पहले सो जाता है।", "p_keybox": "प्रवेश-द्वार का बॉक्स। घर की हर चाबी, हवा से दूर।", "p_router": "wifi के लिए एक ढक्कन। नाइट मोड, भौतिकी द्वारा लागू।", "custom_h2": "कस्टम। हम कुछ भी शील्ड कर सकते हैं।", "custom_p": "हर पीस हाथ से बना है और आपके लिए नाप से बना है। बताइए क्या ख़ामोश होना चाहिए, हम इसी चैट में अपनी शैली में उसका चित्र बनाते हैं, और जब वह चित्र आपको भा जाए, तो असली लोग उसे सिलते हैं और दुनिया भर में भेजते हैं।", "p_carcover": "जब आपकी कार आराम करती है, तो वह हर नेटवर्क से ग़ायब हो जाती है।", "p_studio": "रिकॉर्डिंग स्टूडियो, लैब, मीटिंग रूम। दीवारें जो अपनी साँस थामे रहती हैं।", "on_request1": "अनुरोध पर", "p_research": "लैब, क्लिनिक और हर उस व्यक्ति के लिए मापा गया एटेन्यूएशन, जिसे निश्चितता चाहिए।", "on_request2": "अनुरोध पर", "p_anything": "पर्दे, कवर, परिधान, एनक्लोज़र। अगर आप उसका वर्णन कर सकते हैं, तो हम उसे शील्ड कर सकते हैं।", "on_request3": "अनुरोध पर", "custom_cta": "अपना ख़ुद का पीस बनवाएँ", "why_h2": "हर कोई पहुँच में है। लगभग कोई नहीं चुनता कि कब।", "why_p1": "आपका फ़ोन चौबीसों घंटे टावरों, उपग्रहों, बीकनों और ऐप्स से बात करता रहता है। यह ऐसा करता है <b>आपकी जेब में, आपकी साइड टेबल पर, आपकी मीटिंग्स में</b>। एयरप्लेन मोड उन्हीं कंपनियों का वादा है जो आपकी लोकेशन से कमाई करती हैं। फ़ैराडे केज कोई वादा नहीं है। यह भौतिकी है।", "why_p2": "हर Shield पीस हाथ से बना है, जिसमें जर्मनी में बुना चाँदी-चढ़ा पॉलीएमाइड कपड़ा लगा है, जो 200 MHz से 14 GHz तक 60 dB और उससे अधिक एटेन्यूएशन देता है: 5G, LTE, GPS, wifi, Bluetooth, NFC। सरहदें पार करते पत्रकार, बातचीत में लगे वकील, रिकॉर्डिंग कलाकार, बच्चों को ध्यान का अहसास सिखाते माता-पिता: सबको एक ऐसे पल की ज़रूरत है जब डिवाइस बस <b>वहाँ न हो</b>।", "why_p3": "अनिश्चितता, सोच-समझकर बनाई गई।", "footer_l": "HEISENBAG — बर्लिन में हाथ से बना, दुनिया भर में भेजा गया", "chat_fab": "अपना बनवाएँ", "chat_title": "अपने पीस का वर्णन करें। हम उसका चित्र बनाएँगे।", "chat_btn": "चित्र बनाएँ", "chat_hint": "चित्र मुफ़्त है। अगर वह आपको पसंद आए, तो हम उसे हाथ से बनाकर दुनिया भर में भेजते हैं।", "chat_ph": "एक शील्डेड गिटार केस, गहरा चमड़ा…", "chat_wait": "चित्र बन रहा है, एक पल…", "chat_order": "यह पीस ऑर्डर करें", "chat_fail": "चित्र नहीं बन सका, फिर से कोशिश करें।"}, "id": {"nav_how": "Cara kerjanya", "nav_learn": "Pelajari", "nav_carry": "Bawa", "nav_harness": "Harness", "nav_wear": "Kenakan", "nav_space": "Ruang", "nav_custom": "Kustom", "hero_h1": "Terlalu banyak yang beterbangan di sekitar kita. Kami menutupnya.", "hero_p": "Dibuat tangan di Berlin, dibuat khusus untuk semua orang. Setiap karya Heisenbag Shield membawa sangkar Faraday utuh yang ditenun ke dalam kainnya. Untuk ponsel Anda, mobil Anda, studio Anda, rumah Anda. Tak ada yang perlu diisi daya, tak ada yang perlu dinyalakan, tak ada aplikasi yang harus dipercaya.", "hero_cta": "Lihat 24 karya", "how_h2": "Sangkar logam, ditenun ke dalam kain.", "how_p": "Fisikanya berusia 190 tahun dan tak terkalahkan. Kami hanya membuatnya bisa dikenakan.", "step1": "<b>Gelombang radio adalah listrik di udara.</b> Setiap panggilan, setiap ping GPS, setiap paket LTE adalah medan listrik yang mencari antena ponsel Anda.", "step2": "<b>Jaring konduktif melahap medan listrik.</b> Lapisan dalam setiap produk Shield adalah anyaman halus perak dan logam. Gelombang yang datang mengalir di sekelilingnya, tak pernah menembusnya.", "step3": "<b>Yang tak bisa masuk, tak bisa melacak Anda.</b> Tak ada sinyal yang mencapai perangkat, sehingga perangkat tak melaporkan apa pun: tanpa lokasi, tanpa jabat tangan dengan menara, tanpa data.", "step4": "<b>Tanpa baterai, tanpa aplikasi, tanpa sakelar yang bisa terlupa.</b> Sangkar ini bekerja karena apa adanya, bukan karena apa yang dilakukannya. Ia tak bisa diperbarui, diretas, atau dimatikan.", "learn_h2": "Pahami fisikanya.", "learn_p": "Tiga gagasan menjelaskan semua yang kami buat. Begitu Anda melihatnya, Anda tak akan pernah memandang ponsel dengan cara yang sama.", "learn1_h": "1. Gelombang", "learn1_p": "Radio adalah cahaya yang tak bisa Anda lihat. Keduanya hal yang sama: medan listrik yang beriak di ruang. Ponsel Anda, wifi Anda, satelit GPS Anda, sinar matahari di atas meja: satu keluarga gelombang, panjang yang berbeda. Tak ada yang mistis, semuanya terukur.", "learn2_h": "2. Cahaya", "learn2_p": "Prisma memecah satu berkas menjadi banyak warna karena setiap panjang gelombang membelok secara berbeda. Panjang gelombang menentukan segalanya: gelombang panjang menembus dinding, gelombang pendek membawa data. 5G, LTE, dan Bluetooth hanyalah warna-warna radio, dan seperti setiap warna, sebuah dinding bisa menghentikannya.", "learn3_h": "3. Transmisi", "learn3_p": "Ponsel Anda dan menara saling berteriak tanpa henti, bahkan saat Anda tidur. Teriakan dua arah itulah cara jaringan menemukan Anda, menilai harga Anda, dan mengikuti Anda. Bungkus ponsel dalam sangkar konduktif, dan teriakan itu tak pernah sampai. Hening bukanlah pengaturan. Hening adalah geometri.", "carry_h2": "Bawa.", "carry_p": "Delapan tas dan kantong, dijahit dengan tangan. Masing-masing menutup sangkar sepenuhnya, karena sangkar Faraday yang bercelah hanyalah sebuah tas.", "p_holster": "Dikenakan di sabuk. Ponsel ditarik dalam satu gerakan, disegel dalam satu lipatan.", "p_sling": "Selempang, tinggi di dada. Kunci, kartu, ponsel: gelap.", "p_tote": "Teman sehari-hari. Satu saku di dalam menelan ponsel seutuhnya.", "p_sleeve": "Untuk tablet dan laptop. Rapat tanpa penonton.", "p_backpack": "Roll-top, 20 liter. Satu saku sangkar, zona mati terjamin.", "p_weekender": "Duffel seukuran kabin. Melintasi perbatasan tanpa jejak data.", "p_keyfob": "Menghilangkan kunci mobil Anda dari udara. Pencuri relay hanya mendapat hening.", "p_wallet": "Kartu dan uang tunai. NFC, RFID, dan skimmer terkunci di luar.", "harness_h2": "Harness.", "harness_p": "Dikenakan, bukan dibawa. Tiga harness yang menjaga ponsel tetap di tubuh Anda dan jauh dari udara, sampai Anda memutuskan lain.", "p_harness": "Harness selempang dengan kantong bersangkar. Selalu di tangan, tak pernah online.", "p_chestrig": "Saku sangkar depan penuh, tali utilitas. Rig untuk studio dan panggung.", "p_wrist": "Tali pergelangan dengan saku sangkar mini. Untuk kunci, kartu, satu malam yang tenang.", "wear_h2": "Kenakan.", "wear_p": "Lima pakaian dengan sangkar yang dijahit ke saku, tudung, dan kelim. Anda memakainya seperti pakaian lain; cara kerjanya tak seperti yang lain.", "p_hoodie": "Saku kanguru adalah zona mati. Ponsel masuk, dunia keluar.", "p_parka": "Saku bersangkar yang dalam, tahan badai di luar, tahan sinyal di dalam.", "p_cap": "Enam panel, satu saku tersembunyi. Topi yang hening.", "p_beanie": "Rajutan di luar, perak di dalam. Musim dingin, tanpa pelacakan.", "p_scarf": "Membungkus ponsel yang lupa Anda matikan.", "space_h2": "Ruang.", "space_p": "Delapan karya untuk rumah, kantor, dan perjalanan. Dari tirai yang menggelapkan jendela hingga tenda tempat percakapan tetap menjadi percakapan.", "p_tent": "Ruang privasi pop-up untuk dua orang. Tak ada yang masuk, tak ada yang keluar.", "p_curtain": "Satu panel, panjang penuh. Jendela berhenti mendengarkan.", "p_canopy": "Kanopi boks bayi. Si kecil yang tidur, udara yang paling tenang.", "p_blanket": "Selimut untuk sofa. Perangkat di bawahnya lenyap.", "p_cone": "Kerucut meja untuk rapat. Ponsel masuk, pikiran hadir.", "p_sleepbox": "Kotak samping tempat tidur. Ponsel tidur sebelum Anda.", "p_keybox": "Kotak di pintu masuk. Setiap kunci di rumah, lepas dari udara.", "p_router": "Tudung untuk wifi. Mode malam, ditegakkan oleh fisika.", "custom_h2": "Kustom. Kami melindungi apa saja.", "custom_p": "Setiap karya dibuat tangan dan dibuat khusus untuk Anda. Ceritakan apa yang harus hening, kami menggambarnya dengan gaya kami langsung di chat ini, dan begitu Anda jatuh cinta pada gambarnya, orang sungguhan menjahitnya dan mengirimkannya ke seluruh dunia.", "p_carcover": "Mobil Anda menghilang dari setiap jaringan selama ia tidur.", "p_studio": "Studio rekaman, laboratorium, ruang rapat. Dinding yang menahan napas.", "on_request1": "sesuai permintaan", "p_research": "Atenuasi terukur untuk laboratorium, klinik, dan siapa pun yang membutuhkan kepastian.", "on_request2": "sesuai permintaan", "p_anything": "Tirai, penutup, pakaian, selubung. Jika Anda bisa menggambarkannya, kami bisa melindunginya.", "on_request3": "sesuai permintaan", "custom_cta": "Gambar karya Anda sendiri", "why_h2": "Semua orang bisa dijangkau. Hampir tak ada yang bisa memilih kapan.", "why_p1": "Ponsel Anda berbicara dengan menara, satelit, beacon, dan aplikasi sepanjang waktu. Ia melakukannya <b>di saku Anda, di meja samping tempat tidur Anda, di rapat-rapat Anda</b>. Mode pesawat adalah janji dari perusahaan yang sama yang memonetisasi lokasi Anda. Sangkar Faraday bukan janji. Ia adalah fisika.", "why_p2": "Setiap karya Shield dibuat tangan, dilapisi kain poliamida berlapis perak yang ditenun di Jerman, meredam 60 dB atau lebih dari 200 MHz hingga 14 GHz: 5G, LTE, GPS, wifi, Bluetooth, NFC. Jurnalis yang melintasi perbatasan, pengacara dalam negosiasi, artis rekaman, orang tua yang mengajari anak-anak seperti apa rasanya perhatian: mereka semua membutuhkan satu momen ketika perangkat itu sungguh <b>tidak ada</b>.", "why_p3": "Ketidakpastian, secara sengaja.", "footer_l": "HEISENBAG — Dibuat tangan di Berlin, dikirim ke seluruh dunia", "chat_fab": "Gambar milik Anda", "chat_title": "Ceritakan karya Anda. Kami menggambarnya.", "chat_btn": "Gambar", "chat_hint": "Gambarnya gratis. Jika Anda menyukainya, kami membuatnya dengan tangan dan mengirimkannya ke seluruh dunia.", "chat_ph": "Tas gitar terlindung, kulit gelap…", "chat_wait": "Sedang menggambar, sebentar…", "chat_order": "Pesan karya ini", "chat_fail": "Gagal menggambar, coba lagi."}, "it": {"nav_how": "Come funziona", "nav_learn": "Scopri", "nav_carry": "Portare", "nav_harness": "Imbracature", "nav_wear": "Indossare", "nav_space": "Spazio", "nav_custom": "Su misura", "hero_h1": "C'è troppo che vola nell'aria. Noi lo teniamo fuori.", "hero_p": "Fatto a mano a Berlino, su misura per tutti. Ogni pezzo Heisenbag Shield racchiude una gabbia di Faraday completa, tessuta nella stoffa. Per il tuo telefono, la tua auto, il tuo studio, la tua casa. Niente da ricaricare, niente da accendere, nessuna app di cui fidarsi.", "hero_cta": "Scopri i 24 pezzi", "how_h2": "Una gabbia di metallo, tessuta nella stoffa.", "how_p": "La fisica ha 190 anni ed è imbattibile. Noi l'abbiamo solo resa indossabile.", "step1": "<b>Le onde radio sono elettricità nell'aria.</b> Ogni chiamata, ogni ping GPS, ogni pacchetto LTE è un campo elettrico in cerca dell'antenna del tuo telefono.", "step2": "<b>Una rete conduttiva divora i campi elettrici.</b> La fodera di ogni prodotto Shield è una fine trama di argento e metallo. Le onde in arrivo le scorrono intorno, mai attraverso.", "step3": "<b>Ciò che non può entrare non può seguirti.</b> Nessun segnale raggiunge il dispositivo, quindi il dispositivo non comunica nulla: nessuna posizione, nessun dialogo con l'antenna, nessun dato.", "step4": "<b>Nessuna batteria, nessuna app, nessun interruttore da dimenticare.</b> La gabbia funziona per ciò che è, non per ciò che fa. Non può essere aggiornata, violata o spenta.", "learn_h2": "Scopri la fisica.", "learn_p": "Tre idee spiegano tutto ciò che creiamo. Una volta viste, non guarderai mai più un telefono allo stesso modo.", "learn1_h": "1. Onde", "learn1_p": "La radio è luce che non si vede. Sono la stessa cosa: campi elettrici che si propagano a onde nello spazio. Il tuo telefono, il tuo wifi, il tuo satellite GPS, la luce del sole sul tavolo: un'unica famiglia di onde, lunghezze diverse. Niente di mistico, tutto misurabile.", "learn2_h": "2. Luce", "learn2_p": "Un prisma scompone un raggio in molti colori perché ogni lunghezza d'onda si piega in modo diverso. La lunghezza d'onda decide tutto: le onde lunghe attraversano i muri, quelle corte trasportano dati. 5G, LTE e Bluetooth sono solo colori della radio, e come ogni colore, un muro può fermarli.", "learn3_h": "3. Trasmissione", "learn3_p": "Il tuo telefono e l'antenna si chiamano a gran voce di continuo, anche mentre dormi. È con questo richiamo reciproco che le reti ti trovano, ti prezzano e ti seguono. Avvolgi il telefono in una gabbia conduttiva e il richiamo non arriva mai. Il silenzio non è un'impostazione. È geometria.", "carry_h2": "Portare.", "carry_p": "Otto borse e custodie, cucite a mano. Ognuna si chiude completamente sulla gabbia, perché una gabbia di Faraday con una fessura è solo una borsa.", "p_holster": "Da cintura. Il telefono estratto con un gesto, sigillato con una piega.", "p_sling": "A tracolla, alta sul petto. Chiavi, carta, telefono: al buio.", "p_tote": "La borsa di tutti i giorni. Una tasca interna inghiotte il telefono per intero.", "p_sleeve": "Per tablet e laptop. Riunioni senza pubblico.", "p_backpack": "Roll-top, 20 litri. Una tasca-gabbia, zona morta garantita.", "p_weekender": "Borsone formato cabina. Attraversare i confini senza scia di dati.", "p_keyfob": "Toglie la chiave dell'auto dall'etere. I ladri con relay trovano solo silenzio.", "p_wallet": "Carte e contanti. NFC, RFID e skimmer restano fuori.", "harness_h2": "Imbracature.", "harness_p": "Indossate, non portate. Tre imbracature che tengono il telefono sul tuo corpo e fuori dall'etere, finché non decidi diversamente.", "p_harness": "Imbracatura a tracolla con custodia-gabbia. Sempre a portata di mano, mai online.", "p_chestrig": "Ampia tasca-gabbia frontale, cinghie utility. Il rig per studio e palco.", "p_wrist": "Laccio da polso con mini tasca-gabbia. Per chiavi, carte, una serata tranquilla.", "wear_h2": "Indossare.", "wear_p": "Cinque capi con la gabbia cucita in tasca, cappuccio e orlo. Li indossi come qualsiasi altra cosa; funzionano come nient'altro.", "p_hoodie": "La tasca a marsupio è una zona morta. Telefono dentro, mondo fuori.", "p_parka": "Tasche-gabbia profonde, a prova di tempesta fuori, a prova di segnale dentro.", "p_cap": "Sei pannelli, una tasca nascosta. Il cappellino silenzioso.", "p_beanie": "Maglia fuori, argento dentro. L'inverno, senza tracce.", "p_scarf": "Avvolge il telefono che hai dimenticato di spegnere.", "space_h2": "Spazio.", "space_p": "Otto pezzi per casa, ufficio e viaggio. Da una tenda che oscura una finestra a una tenda da campo dove una conversazione resta una conversazione.", "p_tent": "Stanza privata pop-up per due. Niente entra, niente esce.", "p_curtain": "Un pannello, a tutta altezza. La finestra smette di ascoltare.", "p_canopy": "Baldacchino per culla. Il dormiente più piccolo, l'aria più quieta.", "p_blanket": "Un plaid per il divano. I dispositivi sotto spariscono.", "p_cone": "Cono da tavolo per le riunioni. Telefoni dentro, menti presenti.", "p_sleepbox": "Scatola da comodino. Il telefono si addormenta prima di te.", "p_keybox": "Scatola da ingresso. Ogni chiave di casa, fuori dall'etere.", "p_router": "Una campana per il wifi. Modalità notte, imposta dalla fisica.", "custom_h2": "Su misura. Schermiamo qualsiasi cosa.", "custom_p": "Ogni pezzo è fatto a mano e su misura per te. Descrivi ciò che deve tacere, lo disegniamo nel nostro stile proprio qui in chat e, quando il disegno ti piace, persone vere lo cuciono e lo spediscono in tutto il mondo.", "p_carcover": "La tua auto scompare da ogni rete mentre dorme.", "p_studio": "Studi di registrazione, laboratori, sale riunioni. Pareti che trattengono il respiro.", "on_request1": "su richiesta", "p_research": "Attenuazione misurata per laboratori, cliniche e chiunque abbia bisogno di certezza.", "on_request2": "su richiesta", "p_anything": "Tende, coperture, capi, involucri. Se puoi descriverlo, possiamo schermarlo.", "on_request3": "su richiesta", "custom_cta": "Disegna il tuo pezzo", "why_h2": "Tutti sono raggiungibili. Quasi nessuno sceglie quando.", "why_p1": "Il tuo telefono parla con antenne, satelliti, beacon e app giorno e notte. Lo fa <b>in tasca, sul comodino, durante le tue riunioni</b>. La modalità aereo è una promessa delle stesse aziende che monetizzano la tua posizione. Una gabbia di Faraday non è una promessa. È fisica.", "why_p2": "Ogni pezzo Shield è fatto a mano, foderato con tessuto in poliammide argentato tessuto in Germania, con un'attenuazione di 60 dB e oltre da 200 MHz a 14 GHz: 5G, LTE, GPS, wifi, Bluetooth, NFC. Giornalisti che attraversano confini, avvocati in trattativa, artisti in studio, genitori che insegnano ai figli cosa significa prestare attenzione: tutti hanno bisogno di un momento in cui il dispositivo semplicemente <b>non c'è</b>.", "why_p3": "L'incertezza, per progetto.", "footer_l": "HEISENBAG — Fatto a mano a Berlino, spedito in tutto il mondo", "chat_fab": "Disegna il tuo", "chat_title": "Descrivi il tuo pezzo. Noi lo disegniamo.", "chat_btn": "Disegna", "chat_hint": "Il disegno è gratuito. Se ti piace, lo realizziamo a mano e lo spediamo in tutto il mondo.", "chat_ph": "Una custodia per chitarra schermata, pelle scura…", "chat_wait": "Sto disegnando, un momento…", "chat_order": "Ordina questo pezzo", "chat_fail": "Disegno non riuscito, riprova."}, "ja": {"nav_how": "しくみ", "nav_learn": "物理を知る", "nav_carry": "バッグ", "nav_harness": "ハーネス", "nav_wear": "ウェア", "nav_space": "空間", "nav_custom": "オーダーメイド", "hero_h1": "空中には、あまりに多くのものが飛び交っている。私たちはそれを遮断する。", "hero_p": "ベルリンでハンドメイド、すべての人のためのオーダーメイド。Heisenbag Shield のすべてのアイテムには、生地に織り込まれた完全なファラデーケージが備わっています。あなたの携帯電話、車、スタジオ、家のために。充電するものも、スイッチを入れるものも、信頼すべきアプリもありません。", "hero_cta": "24のアイテムを見る", "how_h2": "布に織り込まれた、金属のケージ。", "how_p": "この物理法則は190年の歴史を持ち、破られることはありません。私たちはそれを身につけられるようにしただけです。", "step1": "<b>電波とは、空気中の電気です。</b>すべての通話、すべての GPS 信号、すべての LTE パケットは、あなたの携帯電話のアンテナを探す電界です。", "step2": "<b>導電性のメッシュは電界を飲み込みます。</b>すべての Shield 製品の裏地は、銀と金属を細かく織り上げた生地です。届いた電波はその周りを流れ、決して通り抜けません。", "step3": "<b>入り込めないものは、あなたを追跡できません。</b>信号がデバイスに届かないので、デバイスは何も報告しません。位置情報も、基地局とのやりとりも、データもありません。", "step4": "<b>バッテリーも、アプリも、切り忘れるスイッチもありません。</b>このケージが機能するのは、何をするかではなく、それが何であるかによるものです。アップデートも、ハッキングも、電源を切ることもできません。", "learn_h2": "物理を知る。", "learn_p": "私たちがつくるすべては、三つの考え方で説明できます。一度それが見えれば、もう二度と携帯電話を同じ目では見られなくなるでしょう。", "learn1_h": "1. 波", "learn1_p": "電波は、目に見えない光です。どちらも同じもの――空間を波打つ電場です。あなたの携帯電話、wifi、GPS 衛星、テーブルに差す日の光。長さが違うだけの、ひとつの波の家族です。神秘的なものは何もなく、すべて測定できます。", "learn2_h": "2. 光", "learn2_p": "プリズムは一本の光を多くの色に分けます。波長ごとに曲がり方が違うからです。波長がすべてを決めます。長い波は壁を通り抜け、短い波はデータを運ぶ。5G、LTE、Bluetooth は電波の色にすぎず、どんな色とも同じように、壁で止めることができます。", "learn3_h": "3. 送信", "learn3_p": "あなたの携帯電話と基地局は、あなたが眠っている間も絶えず呼び合っています。その双方向の呼びかけによって、ネットワークはあなたを見つけ、値踏みし、追いかけます。携帯電話を導電性のケージで包めば、その声は決して届きません。静けさは設定ではありません。幾何学なのです。", "carry_h2": "バッグ。", "carry_p": "手縫いの8つのバッグとポーチ。どれもケージを完全に閉じます。隙間のあるファラデーケージは、ただのバッグにすぎないからです。", "p_holster": "ベルトに装着。ひと動作で取り出し、ひと折りで封じる。", "p_sling": "クロスボディ、胸の高い位置に。鍵、カード、携帯電話を闇の中へ。", "p_tote": "毎日のバッグ。内側のポケットひとつが、携帯電話を丸ごと飲み込む。", "p_sleeve": "タブレットとノートPCのために。聞き手のいない会議を。", "p_backpack": "ロールトップ、20リットル。ケージポケットひとつ、圏外を保証。", "p_weekender": "機内持ち込みサイズのダッフル。データの痕跡を残さない国境越え。", "p_keyfob": "車の鍵を電波から切り離す。リレーアタックの窃盗犯に残るのは沈黙だけ。", "p_wallet": "カードと現金。NFC、RFID、スキマーを締め出す。", "harness_h2": "ハーネス。", "harness_p": "持つのではなく、身につける。あなたが決めるまで、携帯電話を体に留め、電波から遠ざけておく3つのハーネス。", "p_harness": "ケージポーチ付きのクロスボディハーネス。いつも手元に、決してオンラインにはならない。", "p_chestrig": "前面いっぱいのケージポケット、ユーティリティストラップ。スタジオとステージのためのリグ。", "p_wrist": "ミニケージポケット付きのリストストラップ。鍵、カード、そして穏やかな夜ひとつのために。", "wear_h2": "ウェア。", "wear_p": "ポケット、フード、裾にケージを縫い込んだ5つの衣服。ほかの服と同じように着られて、ほかのどんな服とも違う働きをします。", "p_hoodie": "カンガルーポケットは圏外ゾーン。携帯電話は中へ、世界は外へ。", "p_parka": "深いケージポケット。外は嵐を、内は電波を寄せつけない。", "p_cap": "6枚のパネル、ひとつの隠しポケット。静かなキャップ。", "p_beanie": "外はニット、内はシルバー。追跡されない冬。", "p_scarf": "切り忘れた携帯電話を、そっと包み込む。", "space_h2": "空間。", "space_p": "家、オフィス、旅のための8つのアイテム。窓を遮るカーテンから、会話が会話のままでいられるテントまで。", "p_tent": "ふたりのためのポップアップ・プライバシールーム。何も入らず、何も出ていかない。", "p_curtain": "一枚のパネル、床までの丈。窓はもう聞き耳を立てない。", "p_canopy": "ベビーベッドの天蓋。いちばん小さな眠り手に、いちばん静かな空気を。", "p_blanket": "ソファのためのブランケット。その下のデバイスは消え去る。", "p_cone": "会議用の卓上コーン。携帯電話は中に、心はここに。", "p_sleepbox": "ベッドサイドボックス。携帯電話はあなたより先に眠る。", "p_keybox": "玄関用ボックス。家じゅうの鍵を、電波の外へ。", "p_router": "wifi のためのクロッシュ。物理が守るナイトモード。", "custom_h2": "オーダーメイド。どんなものでもシールドします。", "custom_p": "すべてのアイテムはハンドメイド、そしてあなたのためのオーダーメイドです。静かにしたいものを教えてください。このチャットで私たちのスタイルで描きます。その絵を気に入っていただけたら、本物の職人が縫い上げ、世界中へお届けします。", "p_carcover": "眠っている間、あなたの車はあらゆるネットワークから消える。", "p_studio": "レコーディングスタジオ、研究室、会議室。息をひそめる壁。", "on_request1": "受注生産", "p_research": "研究室、クリニック、そして確かさを必要とするすべての人へ。測定済みの減衰性能。", "on_request2": "受注生産", "p_anything": "カーテン、カバー、衣服、エンクロージャー。言葉にできるなら、シールドできます。", "on_request3": "受注生産", "custom_cta": "あなただけのアイテムを描く", "why_h2": "誰もがつながっている。いつつながるかを選べる人は、ほとんどいない。", "why_p1": "あなたの携帯電話は、昼も夜も基地局、衛星、ビーコン、アプリと話しています。それも<b>あなたのポケットの中で、枕元で、会議の最中に</b>。機内モードは、あなたの位置情報で利益を得ている同じ企業からの約束にすぎません。ファラデーケージは約束ではありません。物理なのです。", "why_p2": "すべての Shield アイテムはハンドメイドで、ドイツで織られた銀メッキのポリアミド生地を裏地に使い、200 MHz から 14 GHz まで 60 dB 以上を減衰します。5G、LTE、GPS、wifi、Bluetooth、NFC。国境を越えるジャーナリスト、交渉に臨む弁護士、レコーディングアーティスト、子どもに集中するとはどういうことかを教える親たち。誰もが必要としているのは、デバイスがただ<b>そこにない瞬間</b>です。", "why_p3": "不確定性を、デザインとして。", "footer_l": "HEISENBAG — ベルリンでハンドメイド、世界中へお届け", "chat_fab": "あなたのものを描く", "chat_title": "あなたのアイテムを教えてください。私たちが描きます。", "chat_btn": "描く", "chat_hint": "絵は無料です。気に入っていただけたら、手作りで仕上げて世界中へお届けします。", "chat_ph": "シールド付きのギターケース、ダークレザー…", "chat_wait": "描いています、少々お待ちください…", "chat_order": "このアイテムを注文する", "chat_fail": "描画に失敗しました。もう一度お試しください。"}, "ko": {"nav_how": "작동 원리", "nav_learn": "물리학", "nav_carry": "가방", "nav_harness": "하네스", "nav_wear": "의류", "nav_space": "공간", "nav_custom": "맞춤 제작", "hero_h1": "공기 중에 너무 많은 것이 떠다닙니다. 우리는 그것을 차단합니다.", "hero_p": "베를린에서 손으로 만들고, 모두를 위해 맞춤 제작합니다. 모든 Heisenbag Shield 제품에는 원단에 짜 넣은 완전한 패러데이 케이지가 들어 있습니다. 당신의 휴대폰, 자동차, 스튜디오, 집을 위해. 충전할 것도, 켤 것도, 믿어야 할 앱도 없습니다.", "hero_cta": "24가지 제품 보기", "how_h2": "천에 짜 넣은 금속 케이지.", "how_p": "이 물리 법칙은 190년이 되었고, 뚫을 수 없습니다. 우리는 그저 그것을 입을 수 있게 만들었을 뿐입니다.", "step1": "<b>전파는 공기 중의 전기입니다.</b> 모든 통화, 모든 GPS 신호, 모든 LTE 패킷은 당신의 휴대폰 안테나를 찾아다니는 전기장입니다.", "step2": "<b>전도성 메시는 전기장을 삼킵니다.</b> 모든 Shield 제품의 안감은 은과 금속으로 촘촘하게 짠 직물입니다. 들어오는 전파는 그 주위를 흘러갈 뿐, 결코 통과하지 못합니다.", "step3": "<b>들어올 수 없는 것은 당신을 추적할 수 없습니다.</b> 어떤 신호도 기기에 닿지 않으니, 기기는 아무것도 보고하지 않습니다. 위치도, 기지국과의 교신도, 데이터도 없습니다.", "step4": "<b>배터리도, 앱도, 깜빡할 전원 스위치도 없습니다.</b> 이 케이지는 무엇을 하느냐가 아니라 무엇이냐에 의해 작동합니다. 업데이트될 수도, 해킹될 수도, 꺼질 수도 없습니다.", "learn_h2": "물리학을 이해하세요.", "learn_p": "세 가지 개념이 우리가 만드는 모든 것을 설명합니다. 한번 이해하고 나면, 다시는 휴대폰을 예전처럼 보지 못할 것입니다.", "learn1_h": "1. 파동", "learn1_p": "전파는 눈에 보이지 않는 빛입니다. 둘은 같은 것입니다: 공간을 따라 물결치는 전기장. 당신의 휴대폰, wifi, GPS 위성, 식탁 위의 햇빛: 길이만 다른 하나의 파동 가족입니다. 신비로운 것은 없습니다. 모두 측정할 수 있습니다.", "learn2_h": "2. 빛", "learn2_p": "프리즘은 하나의 빛줄기를 여러 색으로 나눕니다. 파장마다 굴절되는 정도가 다르기 때문입니다. 파장이 모든 것을 결정합니다: 긴 파동은 벽을 통과하고, 짧은 파동은 데이터를 실어 나릅니다. 5G, LTE, Bluetooth는 전파의 색일 뿐이며, 모든 색이 그렇듯 벽이 그것을 막을 수 있습니다.", "learn3_h": "3. 전송", "learn3_p": "당신의 휴대폰과 기지국은 당신이 잠든 동안에도 끊임없이 서로를 부릅니다. 네트워크는 이 쌍방향 외침으로 당신을 찾고, 값을 매기고, 따라다닙니다. 휴대폰을 전도성 케이지로 감싸면 그 외침은 결코 닿지 않습니다. 고요함은 설정이 아닙니다. 기하학입니다.", "carry_h2": "가방.", "carry_p": "손으로 바느질한 여덟 가지 가방과 파우치. 각각 케이지 위로 완전히 닫힙니다. 틈이 있는 패러데이 케이지는 그저 가방일 뿐이니까요.", "p_holster": "벨트에 착용. 한 번의 동작으로 꺼내고, 한 번 접어 봉인합니다.", "p_sling": "크로스바디, 가슴 높이에. 열쇠, 카드, 휴대폰: 어둠 속으로.", "p_tote": "매일 드는 가방. 안쪽 포켓 하나가 휴대폰을 통째로 삼킵니다.", "p_sleeve": "태블릿과 노트북을 위해. 청중 없는 회의.", "p_backpack": "롤탑, 20리터. 케이지 포켓 하나, 신호 사각지대 보장.", "p_weekender": "기내용 사이즈 더플백. 데이터 흔적 없는 국경 통과.", "p_keyfob": "자동차 키를 전파에서 떼어 놓습니다. 릴레이 도둑에게 남는 건 침묵뿐.", "p_wallet": "카드와 현금. NFC, RFID, 스키머를 차단합니다.", "harness_h2": "하네스.", "harness_p": "드는 것이 아니라 입는 것. 당신이 달리 결정하기 전까지 휴대폰을 몸에 두고 전파로부터 떼어 놓는 세 가지 하네스.", "p_harness": "케이지 파우치가 달린 크로스바디 하네스. 언제나 손닿는 곳에, 결코 온라인은 아니게.", "p_chestrig": "전면 전체가 케이지 포켓, 다용도 스트랩. 스튜디오와 무대를 위한 장비.", "p_wrist": "미니 케이지 포켓이 달린 손목 스트랩. 열쇠와 카드, 그리고 고요한 저녁 하나를 위해.", "wear_h2": "의류.", "wear_p": "포켓, 후드, 밑단에 케이지를 꿰매 넣은 다섯 가지 옷. 여느 옷처럼 입지만, 그 어떤 옷과도 다르게 작동합니다.", "p_hoodie": "캥거루 포켓은 신호 사각지대. 휴대폰은 안으로, 세상은 밖으로.", "p_parka": "깊은 케이지 포켓. 겉은 폭풍을, 속은 신호를 막습니다.", "p_cap": "여섯 개의 패널, 하나의 숨은 포켓. 조용한 모자.", "p_beanie": "겉은 니트, 속은 실버. 추적 없는 겨울.", "p_scarf": "끄는 걸 잊은 휴대폰을 감싸 줍니다.", "space_h2": "공간.", "space_p": "집, 사무실, 여행을 위한 여덟 가지 제품. 창문을 가리는 커튼부터, 대화가 대화로 남는 텐트까지.", "p_tent": "두 사람을 위한 팝업 프라이버시 룸. 들어오는 것도, 나가는 것도 없습니다.", "p_curtain": "한 장의 패널, 바닥까지 닿는 길이. 창문이 더 이상 엿듣지 않습니다.", "p_canopy": "아기 침대 캐노피. 가장 작은 잠꾸러기, 가장 고요한 공기.", "p_blanket": "소파를 위한 담요. 그 아래의 기기는 사라집니다.", "p_cone": "회의용 탁상 콘. 휴대폰은 안에, 마음은 이 자리에.", "p_sleepbox": "침대 옆 박스. 휴대폰이 당신보다 먼저 잠듭니다.", "p_keybox": "현관 박스. 집 안의 모든 열쇠를 전파 밖으로.", "p_router": "wifi를 위한 클로슈. 물리학이 지켜 주는 야간 모드.", "custom_h2": "맞춤 제작. 무엇이든 차폐합니다.", "custom_p": "모든 제품은 손으로, 당신을 위해 맞춤 제작됩니다. 무엇이 조용해져야 하는지 설명해 주시면, 바로 여기 채팅에서 우리 스타일로 그려 드립니다. 그 그림이 마음에 드시면, 실제 사람들이 바느질해 전 세계로 보내 드립니다.", "p_carcover": "당신의 차가 잠든 동안 모든 네트워크에서 사라집니다.", "p_studio": "녹음 스튜디오, 연구실, 회의실. 숨을 죽이는 벽.", "on_request1": "요청 시 제작", "p_research": "연구실, 병원, 그리고 확신이 필요한 모든 이를 위한 측정된 감쇠.", "on_request2": "요청 시 제작", "p_anything": "커튼, 커버, 의류, 인클로저. 설명할 수 있다면, 차폐할 수 있습니다.", "on_request3": "요청 시 제작", "custom_cta": "나만의 제품 그리기", "why_h2": "누구에게나 닿을 수 있습니다. 그 시점을 고르는 사람은 거의 없습니다.", "why_p1": "당신의 휴대폰은 하루 종일 기지국, 위성, 비컨, 앱과 대화합니다. 그것도 <b>당신의 주머니 속에서, 침대 머리맡에서, 회의 중에</b> 말이죠. 비행기 모드는 당신의 위치로 돈을 버는 바로 그 기업들이 하는 약속입니다. 패러데이 케이지는 약속이 아닙니다. 물리 법칙입니다.", "why_p2": "모든 Shield 제품은 손으로 만들어지며, 독일에서 직조한 은도금 폴리아미드 원단으로 안감을 대어 200 MHz부터 14 GHz까지 60 dB 이상을 감쇠합니다: 5G, LTE, GPS, wifi, Bluetooth, NFC. 국경을 넘는 기자, 협상 중인 변호사, 레코딩 아티스트, 아이에게 집중이 어떤 느낌인지 가르치는 부모: 모두에게 필요한 것은 기기가 그저 <b>그곳에 없는 순간</b>입니다.", "why_p3": "의도된 불확정성.", "footer_l": "HEISENBAG — 베를린 핸드메이드, 전 세계 배송", "chat_fab": "나만의 것 그리기", "chat_title": "당신의 제품을 설명하세요. 우리가 그려 드립니다.", "chat_btn": "그리기", "chat_hint": "그림은 무료입니다. 마음에 드시면 손으로 만들어 전 세계로 보내 드립니다.", "chat_ph": "차폐 기능이 있는 기타 케이스, 어두운 가죽…", "chat_wait": "그리는 중입니다, 잠시만요…", "chat_order": "이 제품 주문하기", "chat_fail": "그리기에 실패했습니다. 다시 시도해 주세요."}, "pl": {"nav_how": "Jak to działa", "nav_learn": "Fizyka", "nav_carry": "Torby", "nav_harness": "Uprzęże", "nav_wear": "Odzież", "nav_space": "Przestrzeń", "nav_custom": "Na zamówienie", "hero_h1": "Za dużo krąży w powietrzu. My to odcinamy.", "hero_p": "Ręcznie robione w Berlinie, na zamówienie dla każdego. W każdy element Heisenbag Shield wpleciona jest pełna klatka Faradaya. Dla twojego telefonu, twojego auta, twojego studia, twojego domu. Nic do ładowania, nic do włączania, żadnej aplikacji, której trzeba ufać.", "hero_cta": "Zobacz wszystkie 24 rzeczy", "how_h2": "Metalowa klatka, wpleciona w tkaninę.", "how_p": "Ta fizyka ma 190 lat i nie da się jej pokonać. My po prostu sprawiliśmy, że można ją nosić.", "step1": "<b>Fale radiowe to elektryczność w powietrzu.</b> Każde połączenie, każdy sygnał GPS, każdy pakiet LTE to pole elektryczne szukające anteny twojego telefonu.", "step2": "<b>Przewodząca siatka pochłania pola elektryczne.</b> Podszewka każdego produktu Shield to drobny splot srebra i metalu. Nadchodzące fale opływają ją, nigdy nie przenikają.", "step3": "<b>Co nie może wejść do środka, nie może cię śledzić.</b> Żaden sygnał nie dociera do urządzenia, więc urządzenie niczego nie zgłasza: ani lokalizacji, ani połączenia z masztem, ani danych.", "step4": "<b>Bez baterii, bez aplikacji, bez wyłącznika, o którym można zapomnieć.</b> Klatka działa dzięki temu, czym jest, a nie temu, co robi. Nie da się jej zaktualizować, zhakować ani wyłączyć.", "learn_h2": "Poznaj fizykę.", "learn_p": "Trzy idee wyjaśniają wszystko, co tworzymy. Gdy je zobaczysz, już nigdy nie spojrzysz na telefon tak samo.", "learn1_h": "1. Fale", "learn1_p": "Radio to światło, którego nie widzisz. Jedno i drugie to to samo: pola elektryczne falujące w przestrzeni. Twój telefon, twoje wifi, twój satelita GPS, światło słońca na stole — jedna rodzina fal, różne długości. Nic mistycznego, wszystko mierzalne.", "learn2_h": "2. Światło", "learn2_p": "Pryzmat rozszczepia jeden promień na wiele barw, bo każda długość fali załamuje się inaczej. Długość fali decyduje o wszystkim: długie fale przenikają przez ściany, krótkie niosą dane. 5G, LTE i Bluetooth to po prostu barwy radia — i jak każdą barwę, może je zatrzymać ściana.", "learn3_h": "3. Transmisja", "learn3_p": "Twój telefon i maszt bez przerwy się nawołują, nawet gdy śpisz. To dwustronne nawoływanie pozwala sieciom cię znaleźć, wycenić i śledzić. Owiń telefon przewodzącą klatką, a wołanie nigdy nie dotrze. Cisza to nie ustawienie. To geometria.", "carry_h2": "Torby.", "carry_p": "Osiem toreb i etui, szytych ręcznie. Każde zamyka się całkowicie nad klatką, bo klatka Faradaya ze szczeliną to po prostu torba.", "p_holster": "Noszony przy pasku. Telefon wyjęty jednym ruchem, zamknięty jednym złożeniem.", "p_sling": "Na skos, wysoko na piersi. Klucze, karta, telefon: w ciemności.", "p_tote": "Na co dzień. Jedna wewnętrzna kieszeń połyka telefon w całości.", "p_sleeve": "Na tablet i laptopa. Spotkania bez publiczności.", "p_backpack": "Roll-top, 20 litrów. Jedna kieszeń-klatka, martwa strefa gwarantowana.", "p_weekender": "Torba podróżna w rozmiarze bagażu podręcznego. Przekraczanie granic bez cyfrowego śladu.", "p_keyfob": "Zdejmuje kluczyk do auta z eteru. Złodzieje na przekaźnik słyszą tylko ciszę.", "p_wallet": "Karty i gotówka. NFC, RFID i skimmery zostają za drzwiami.", "harness_h2": "Uprzęże.", "harness_p": "Noszone na sobie, nie w ręku. Trzy uprzęże, które trzymają telefon przy ciele i poza eterem — dopóki nie zdecydujesz inaczej.", "p_harness": "Uprząż na skos z ekranowaną saszetką. Zawsze pod ręką, nigdy online.", "p_chestrig": "Pełna przednia kieszeń-klatka, paski użytkowe. Zestaw na studio i scenę.", "p_wrist": "Pasek na nadgarstek z mini kieszenią-klatką. Na klucze, karty i jeden spokojny wieczór.", "wear_h2": "Odzież.", "wear_p": "Pięć ubrań z klatką wszytą w kieszeń, kaptur i obszycie. Nosisz je jak wszystko inne; działają jak nic innego.", "p_hoodie": "Kieszeń kangurka to martwa strefa. Telefon do środka, świat na zewnątrz.", "p_parka": "Głębokie ekranowane kieszenie. Odporna na burzę z zewnątrz, na sygnał od środka.", "p_cap": "Sześć paneli, jedna ukryta kieszeń. Cicha czapka.", "p_beanie": "Na zewnątrz dzianina, w środku srebro. Zima bez śledzenia.", "p_scarf": "Otula telefon, którego zapomniałeś wyłączyć.", "space_h2": "Przestrzeń.", "space_p": "Osiem rzeczy do domu, biura i w podróż. Od zasłony, która zaciemnia okno, po namiot, w którym rozmowa pozostaje rozmową.", "p_tent": "Rozkładany pokój prywatności dla dwojga. Nic do środka, nic na zewnątrz.", "p_curtain": "Jeden panel, pełna długość. Okno przestaje słuchać.", "p_canopy": "Baldachim na łóżeczko. Najmniejszy śpioch, najcichsze powietrze.", "p_blanket": "Narzuta na sofę. Urządzenia pod nią znikają.", "p_cone": "Stożek na stół na spotkania. Telefony w środku, umysły obecne.", "p_sleepbox": "Pudełko przy łóżku. Telefon zasypia przed tobą.", "p_keybox": "Pudełko do przedpokoju. Wszystkie klucze w domu, poza eterem.", "p_router": "Klosz na wifi. Tryb nocny, wymuszony przez fizykę.", "custom_h2": "Na zamówienie. Ekranujemy wszystko.", "custom_p": "Każda rzecz jest robiona ręcznie i na zamówienie dla ciebie. Opisz, co ma ucichnąć, narysujemy to w naszym stylu tutaj, na czacie, a gdy pokochasz rysunek, prawdziwi ludzie to uszyją i wyślą w dowolne miejsce na świecie.", "p_carcover": "Twoje auto znika ze wszystkich sieci, kiedy śpi.", "p_studio": "Studia nagraniowe, laboratoria, sale konferencyjne. Ściany, które wstrzymują oddech.", "on_request1": "na zapytanie", "p_research": "Zmierzone tłumienie dla laboratoriów, klinik i wszystkich, którzy potrzebują pewności.", "on_request2": "na zapytanie", "p_anything": "Zasłony, pokrowce, ubrania, obudowy. Jeśli potrafisz to opisać, potrafimy to ekranować.", "on_request3": "na zapytanie", "custom_cta": "Narysuj własną rzecz", "why_h2": "Każdy jest osiągalny. Prawie nikt nie wybiera, kiedy.", "why_p1": "Twój telefon przez całą dobę rozmawia z masztami, satelitami, beaconami i aplikacjami. Robi to <b>w twojej kieszeni, na twojej szafce nocnej, na twoich spotkaniach</b>. Tryb samolotowy to obietnica tych samych firm, które zarabiają na twojej lokalizacji. Klatka Faradaya nie jest obietnicą. Jest fizyką.", "why_p2": "Każdy element Shield jest szyty ręcznie i wyłożony posrebrzaną tkaniną poliamidową tkaną w Niemczech, tłumiąc 60 dB i więcej w zakresie od 200 MHz do 14 GHz: 5G, LTE, GPS, wifi, Bluetooth, NFC. Dziennikarze przekraczający granice, prawnicy w negocjacjach, artyści w studiu, rodzice uczący dzieci, jak smakuje uwaga: wszyscy potrzebują chwili, w której urządzenia po prostu <b>nie ma</b>.", "why_p3": "Nieoznaczoność, z założenia.", "footer_l": "HEISENBAG — Ręcznie robione w Berlinie, wysyłka na cały świat", "chat_fab": "Narysuj swoją", "chat_title": "Opisz swoją rzecz. My ją narysujemy.", "chat_btn": "Narysuj", "chat_hint": "Rysunek jest bezpłatny. Jeśli go pokochasz, wykonamy rzecz ręcznie i wyślemy w dowolne miejsce na świecie.", "chat_ph": "Ekranowany futerał na gitarę, ciemna skóra…", "chat_wait": "Rysujemy, chwileczkę…", "chat_order": "Zamów tę rzecz", "chat_fail": "Nie udało się narysować, spróbuj ponownie."}, "pt": {"nav_how": "Como funciona", "nav_learn": "Aprender", "nav_carry": "Levar", "nav_harness": "Arneses", "nav_wear": "Vestir", "nav_space": "Espaço", "nav_custom": "Por medida", "hero_h1": "Há demasiado a voar pelo ar. Nós deixamo-lo de fora.", "hero_p": "Feito à mão em Berlim, por medida para todos. Cada peça Heisenbag Shield traz uma gaiola de Faraday completa, tecida no próprio tecido. Para o seu telemóvel, o seu carro, o seu estúdio, a sua casa. Nada para carregar, nada para ligar, nenhuma app em que confiar.", "hero_cta": "Ver as 24 peças", "how_h2": "Uma gaiola de metal, tecida em pano.", "how_p": "A física tem 190 anos e é imbatível. Nós apenas a tornámos vestível.", "step1": "<b>As ondas de rádio são eletricidade no ar.</b> Cada chamada, cada sinal de GPS, cada pacote LTE é um campo elétrico à procura da antena do seu telemóvel.", "step2": "<b>Uma malha condutora devora campos elétricos.</b> O forro de cada produto Shield é uma trama fina de prata e metal. As ondas que chegam fluem à sua volta, nunca através dela.", "step3": "<b>O que não consegue entrar não o consegue seguir.</b> Nenhum sinal chega ao dispositivo, por isso o dispositivo não comunica nada: nem localização, nem contacto com a antena, nem dados.", "step4": "<b>Sem bateria, sem app, sem interruptor para esquecer.</b> A gaiola funciona pelo que é, não pelo que faz. Não pode ser atualizada, pirateada nem desligada.", "learn_h2": "Aprenda a física.", "learn_p": "Três ideias explicam tudo o que fazemos. Depois de as ver, nunca mais olhará para um telemóvel da mesma forma.", "learn1_h": "1. Ondas", "learn1_p": "A rádio é luz que não se vê. Ambas são a mesma coisa: campos elétricos que ondulam pelo espaço. O seu telemóvel, o seu wifi, o seu satélite GPS, a luz do sol sobre a mesa: uma só família de ondas, comprimentos diferentes. Nada de místico, tudo mensurável.", "learn2_h": "2. Luz", "learn2_p": "Um prisma divide um feixe em muitas cores porque cada comprimento de onda se curva de forma diferente. O comprimento de onda decide tudo: as ondas longas atravessam paredes, as curtas transportam dados. 5G, LTE e Bluetooth são apenas cores da rádio e, como qualquer cor, uma parede pode detê-las.", "learn3_h": "3. Transmissão", "learn3_p": "O seu telemóvel e a antena gritam um para o outro sem parar, mesmo enquanto dorme. É com esse grito de ida e volta que as redes o encontram, lhe põem um preço e o seguem. Envolva o telemóvel numa gaiola condutora e o grito nunca chega. O silêncio não é uma definição. É geometria.", "carry_h2": "Levar.", "carry_p": "Oito sacos e bolsas, cosidos à mão. Cada um fecha-se por completo sobre a gaiola, porque uma gaiola de Faraday com uma abertura é apenas um saco.", "p_holster": "Usado no cinto. O telemóvel sai num gesto e fica selado numa dobra.", "p_sling": "A tiracolo, alto no peito. Chaves, cartão, telemóvel: no escuro.", "p_tote": "O saco do dia a dia. Um bolso interior engole o telemóvel inteiro.", "p_sleeve": "Para tablet e portátil. Reuniões sem plateia.", "p_backpack": "Roll-top, 20 litros. Um bolso-gaiola, zona morta garantida.", "p_weekender": "Saco de viagem tamanho cabine. Atravessar fronteiras sem rasto de dados.", "p_keyfob": "Tira a chave do seu carro do ar. Os ladrões por relay só encontram silêncio.", "p_wallet": "Cartões e dinheiro. NFC, RFID e skimmers ficam de fora.", "harness_h2": "Arneses.", "harness_p": "Vestidos, não carregados. Três arneses que mantêm o telemóvel junto ao corpo e fora do ar até decidir o contrário.", "p_harness": "Arnês a tiracolo com bolsa-gaiola. Sempre à mão, nunca online.", "p_chestrig": "Grande bolso-gaiola frontal, correias utilitárias. O rig para estúdio e palco.", "p_wrist": "Pulseira com mini bolso-gaiola. Para chaves, cartões, uma noite tranquila.", "wear_h2": "Vestir.", "wear_p": "Cinco peças de roupa com a gaiola cosida no bolso, no capuz e na bainha. Veste-as como qualquer outra coisa; funcionam como nenhuma outra.", "p_hoodie": "O bolso canguru é uma zona morta. Telemóvel dentro, mundo fora.", "p_parka": "Bolsos-gaiola fundos, à prova de tempestade por fora, à prova de sinal por dentro.", "p_cap": "Seis painéis, um bolso escondido. O boné silencioso.", "p_beanie": "Malha por fora, prata por dentro. O inverno, sem rasto.", "p_scarf": "Envolve o telemóvel que se esqueceu de desligar.", "space_h2": "Espaço.", "space_p": "Oito peças para casa, escritório e viagem. Desde uma cortina que escurece uma janela até uma tenda onde uma conversa continua a ser uma conversa.", "p_tent": "Sala privada pop-up para dois. Nada entra, nada sai.", "p_curtain": "Um painel, comprimento total. A janela deixa de escutar.", "p_canopy": "Dossel para berço. O mais pequeno dorminhoco, o ar mais sereno.", "p_blanket": "Uma manta para o sofá. Os dispositivos por baixo desaparecem.", "p_cone": "Cone de mesa para reuniões. Telemóveis dentro, mentes presentes.", "p_sleepbox": "Caixa de mesa de cabeceira. O telemóvel adormece antes de si.", "p_keybox": "Caixa de entrada. Todas as chaves da casa, fora do ar.", "p_router": "Uma campânula para o wifi. Modo noturno, imposto pela física.", "custom_h2": "Por medida. Blindamos tudo.", "custom_p": "Cada peça é feita à mão e por medida para si. Descreva o que deve ficar em silêncio, nós desenhamo-lo no nosso estilo aqui mesmo no chat e, quando se apaixonar pelo desenho, pessoas reais cosem-no e enviam-no para todo o mundo.", "p_carcover": "O seu carro desaparece de todas as redes enquanto dorme.", "p_studio": "Estúdios de gravação, laboratórios, salas de reunião. Paredes que sustêm a respiração.", "on_request1": "sob pedido", "p_research": "Atenuação medida para laboratórios, clínicas e todos os que precisam de certeza.", "on_request2": "sob pedido", "p_anything": "Cortinas, capas, roupa, invólucros. Se o consegue descrever, nós conseguimos blindá-lo.", "on_request3": "sob pedido", "custom_cta": "Desenhe a sua peça", "why_h2": "Todos estão contactáveis. Quase ninguém escolhe quando.", "why_p1": "O seu telemóvel fala com antenas, satélites, beacons e apps a toda a hora. Fá-lo <b>no seu bolso, na sua mesa de cabeceira, nas suas reuniões</b>. O modo de voo é uma promessa das mesmas empresas que monetizam a sua localização. Uma gaiola de Faraday não é uma promessa. É física.", "why_p2": "Cada peça Shield é feita à mão, forrada com tecido de poliamida prateada tecido na Alemanha, com uma atenuação de 60 dB ou mais de 200 MHz a 14 GHz: 5G, LTE, GPS, wifi, Bluetooth, NFC. Jornalistas a atravessar fronteiras, advogados em negociações, artistas em estúdio, pais que ensinam aos filhos o que é a atenção: todos precisam de um momento em que o dispositivo simplesmente <b>não está lá</b>.", "why_p3": "Incerteza, por design.", "footer_l": "HEISENBAG — Feito à mão em Berlim, enviado para todo o mundo", "chat_fab": "Desenhe a sua", "chat_title": "Descreva a sua peça. Nós desenhamo-la.", "chat_btn": "Desenhar", "chat_hint": "O desenho é gratuito. Se gostar, fazemo-lo à mão e enviamos para todo o mundo.", "chat_ph": "Um estojo de guitarra blindado, couro escuro…", "chat_wait": "A desenhar, um momento…", "chat_order": "Encomendar esta peça", "chat_fail": "O desenho falhou, tente novamente."}, "ru": {"nav_how": "Как это работает", "nav_learn": "Физика", "nav_carry": "Сумки", "nav_harness": "Портупеи", "nav_wear": "Одежда", "nav_space": "Пространство", "nav_custom": "На заказ", "hero_h1": "Вокруг слишком много всего летает. Мы это отсекаем.", "hero_p": "Сделано вручную в Берлине, на заказ — для каждого. В каждое изделие Heisenbag Shield вплетена полноценная клетка Фарадея. Для вашего телефона, вашей машины, вашей студии, вашего дома. Нечего заряжать, нечего включать, никаких приложений, которым приходится доверять.", "hero_cta": "Смотреть все 24 изделия", "how_h2": "Металлическая клетка, вплетённая в ткань.", "how_p": "Этой физике 190 лет, и её не обойти. Мы просто сделали её носимой.", "step1": "<b>Радиоволны — это электричество в воздухе.</b> Каждый звонок, каждый GPS-сигнал, каждый LTE-пакет — это электрическое поле, которое ищет антенну вашего телефона.", "step2": "<b>Проводящая сетка поглощает электрические поля.</b> Подкладка каждого изделия Shield — тонкое плетение из серебра и металла. Входящие волны обтекают его, но никогда не проходят насквозь.", "step3": "<b>То, что не может проникнуть внутрь, не может вас отследить.</b> Ни один сигнал не достигает устройства, и устройство ничего не сообщает: ни местоположения, ни связи с вышкой, ни данных.", "step4": "<b>Ни батареи, ни приложения, ни выключателя, о котором можно забыть.</b> Клетка работает благодаря тому, чем она является, а не тому, что она делает. Её нельзя обновить, взломать или выключить.", "learn_h2": "Поймите физику.", "learn_p": "Три идеи объясняют всё, что мы делаем. Однажды увидев их, вы уже никогда не посмотрите на телефон по-прежнему.", "learn1_h": "1. Волны", "learn1_p": "Радио — это свет, которого вы не видите. По сути это одно и то же: электрические поля, расходящиеся рябью в пространстве. Ваш телефон, ваш wifi, ваш спутник GPS, солнечный свет на столе — одно семейство волн, только разной длины. Никакой мистики, всё измеримо.", "learn2_h": "2. Свет", "learn2_p": "Призма раскладывает один луч на множество цветов, потому что каждая длина волны преломляется по-своему. Длина волны решает всё: длинные волны проходят сквозь стены, короткие несут данные. 5G, LTE и Bluetooth — просто цвета радио, и, как любой цвет, их может остановить стена.", "learn3_h": "3. Передача", "learn3_p": "Ваш телефон и вышка постоянно перекрикиваются, даже когда вы спите. Именно по этой перекличке сети находят вас, оценивают вас и следуют за вами. Заключите телефон в проводящую клетку — и крик никуда не дойдёт. Тишина — это не настройка. Это геометрия.", "carry_h2": "Сумки.", "carry_p": "Восемь сумок и чехлов, сшитых вручную. Каждый полностью смыкается над клеткой, ведь клетка Фарадея с зазором — это просто сумка.", "p_holster": "Носится на поясе. Телефон достаётся одним движением и запечатывается одним сгибом.", "p_sling": "Через плечо, высоко на груди. Ключи, карта, телефон — в темноте.", "p_tote": "Сумка на каждый день. Внутренний карман целиком поглощает телефон.", "p_sleeve": "Для планшета и ноутбука. Встречи без лишних слушателей.", "p_backpack": "Ролл-топ, 20 литров. Один карман-клетка, мёртвая зона гарантирована.", "p_weekender": "Дорожная сумка размером с ручную кладь. Пересечение границ без цифрового следа.", "p_keyfob": "Уводит ключ от машины из эфира. Угонщикам с ретранслятором — только тишина.", "p_wallet": "Карты и наличные. NFC, RFID и скиммеры остаются снаружи.", "harness_h2": "Портупеи.", "harness_p": "Их носят на себе, а не в руках. Три портупеи держат телефон на теле и вне эфира — пока вы не решите иначе.", "p_harness": "Портупея через плечо с экранированным подсумком. Всегда под рукой, никогда онлайн.", "p_chestrig": "Полноразмерный нагрудный карман-клетка, утилитарные ремни. Снаряжение для студии и сцены.", "p_wrist": "Ремешок на запястье с мини-карманом-клеткой. Для ключей, карт и одного спокойного вечера.", "wear_h2": "Одежда.", "wear_p": "Пять вещей с клеткой, вшитой в карман, капюшон и подол. Вы носите их как любую другую одежду; работают они как ничто другое.", "p_hoodie": "Карман-кенгуру — мёртвая зона. Телефон внутрь, мир наружу.", "p_parka": "Глубокие экранированные карманы. Снаружи не боится шторма, внутри — сигнала.", "p_cap": "Шесть клиньев, один потайной карман. Тихая кепка.", "p_beanie": "Снаружи вязка, внутри серебро. Зима без слежки.", "p_scarf": "Укутает телефон, который вы забыли выключить.", "space_h2": "Пространство.", "space_p": "Восемь изделий для дома, офиса и путешествий. От шторы, затемняющей окно, до палатки, где разговор остаётся разговором.", "p_tent": "Раскладная комната приватности на двоих. Ничего внутрь, ничего наружу.", "p_curtain": "Одно полотно в полную длину. Окно перестаёт подслушивать.", "p_canopy": "Балдахин для детской кроватки. Самый маленький соня, самый тихий воздух.", "p_blanket": "Плед для дивана. Устройства под ним исчезают.", "p_cone": "Настольный конус для встреч. Телефоны внутри, мысли здесь.", "p_sleepbox": "Прикроватный бокс. Телефон засыпает раньше вас.", "p_keybox": "Бокс для прихожей. Все ключи в доме — вне эфира.", "p_router": "Колпак для wifi. Ночной режим, гарантированный физикой.", "custom_h2": "На заказ. Мы экранируем что угодно.", "custom_p": "Каждое изделие сделано вручную и на заказ — специально для вас. Опишите, что должно замолчать, мы нарисуем это в нашем стиле прямо здесь, в чате, а когда рисунок вам полюбится, живые люди сошьют изделие и отправят его в любую точку мира.", "p_carcover": "Ваш автомобиль исчезает из всех сетей, пока спит.", "p_studio": "Студии звукозаписи, лаборатории, переговорные. Стены, затаившие дыхание.", "on_request1": "по запросу", "p_research": "Измеренное затухание для лабораторий, клиник и всех, кому нужна уверенность.", "on_request2": "по запросу", "p_anything": "Шторы, чехлы, одежда, укрытия. Если вы можете это описать, мы можем это экранировать.", "on_request3": "по запросу", "custom_cta": "Нарисуйте своё изделие", "why_h2": "До каждого можно дотянуться. Почти никто не выбирает, когда.", "why_p1": "Ваш телефон круглосуточно говорит с вышками, спутниками, маяками и приложениями. Он делает это <b>в вашем кармане, на прикроватной тумбочке, на ваших встречах</b>. Авиарежим — это обещание тех же компаний, которые зарабатывают на вашем местоположении. Клетка Фарадея — не обещание. Это физика.", "why_p2": "Каждое изделие Shield сделано вручную и подбито посеребрённой полиамидной тканью, сотканной в Германии, с ослаблением 60 dB и более в диапазоне от 200 MHz до 14 GHz: 5G, LTE, GPS, wifi, Bluetooth, NFC. Журналистам на границе, юристам на переговорах, музыкантам в студии, родителям, которые учат детей тому, каково это — быть внимательным: всем им нужен момент, когда устройства просто <b>нет рядом</b>.", "why_p3": "Неопределённость — по замыслу.", "footer_l": "HEISENBAG — Сделано вручную в Берлине, доставка по всему миру", "chat_fab": "Нарисовать своё", "chat_title": "Опишите своё изделие. Мы его нарисуем.", "chat_btn": "Нарисовать", "chat_hint": "Рисунок бесплатный. Если он вам понравится, мы сделаем изделие вручную и отправим в любую точку мира.", "chat_ph": "Экранированный кейс для гитары, тёмная кожа…", "chat_wait": "Рисуем, минутку…", "chat_order": "Заказать это изделие", "chat_fail": "Не удалось нарисовать, попробуйте ещё раз."}, "sw": {"nav_how": "Jinsi inavyofanya kazi", "nav_learn": "Jifunze", "nav_carry": "Beba", "nav_harness": "Mkanda", "nav_wear": "Vaa", "nav_space": "Nafasi", "nav_custom": "Maalum", "hero_h1": "Kuna mengi mno yanayoruka huku na huko. Tunayafungia nje.", "hero_p": "Imetengenezwa kwa mkono Berlin, imetengenezwa maalum kwa kila mtu. Kila kipande cha Heisenbag Shield kina kizimba kamili cha Faraday kilichofumwa ndani ya kitambaa. Kwa simu yako, gari lako, studio yako, nyumba yako. Hakuna cha kuchaji, hakuna cha kuwasha, hakuna programu ya kuamini.", "hero_cta": "Tazama vipande 24", "how_h2": "Kizimba cha chuma, kilichofumwa ndani ya kitambaa.", "how_p": "Fizikia hii ina umri wa miaka 190 na haishindiki. Sisi tumeifanya tu ivalike.", "step1": "<b>Mawimbi ya redio ni umeme ulio hewani.</b> Kila simu, kila ishara ya GPS, kila kifurushi cha LTE ni uga wa umeme unaotafuta antena ya simu yako.", "step2": "<b>Wavu unaopitisha umeme humeza sehemu za umeme.</b> Bitana ya kila bidhaa ya Shield ni ufumaji mwembamba wa fedha na chuma. Mawimbi yanayokuja hutiririka kuuzunguka, kamwe hayapiti ndani yake.", "step3": "<b>Kisichoweza kuingia hakiwezi kukufuatilia.</b> Hakuna ishara inayofika kwenye kifaa, kwa hivyo kifaa hakiripoti chochote: hakuna mahali, hakuna mawasiliano na mnara, hakuna data.", "step4": "<b>Hakuna betri, hakuna programu, hakuna swichi ya kusahau.</b> Kizimba hiki hufanya kazi kwa sababu ya kilivyo, si kwa sababu ya kile kinachofanya. Hakiwezi kusasishwa, kudukuliwa, wala kuzimwa.", "learn_h2": "Ijue fizikia.", "learn_p": "Mawazo matatu yanaeleza kila kitu tunachotengeneza. Ukishayaona, hutaitazama simu kwa namna ileile tena.", "learn1_h": "1. Mawimbi", "learn1_p": "Redio ni mwanga usioweza kuuona. Vyote viwili ni kitu kimoja: sehemu za umeme zinazopiga mawimbi angani. Simu yako, wifi yako, setilaiti yako ya GPS, mwanga wa jua juu ya meza: familia moja ya mawimbi, urefu tofauti. Hakuna fumbo, kila kitu kinapimika.", "learn2_h": "2. Mwanga", "learn2_p": "Prizimu hugawanya mwali mmoja kuwa rangi nyingi kwa sababu kila urefu wa wimbi hupinda kwa namna tofauti. Urefu wa wimbi huamua kila kitu: mawimbi marefu hupenya kuta, mafupi hubeba data. 5G, LTE na Bluetooth ni rangi tu za redio, na kama kila rangi, ukuta unaweza kuzizuia.", "learn3_h": "3. Usambazaji", "learn3_p": "Simu yako na mnara huitana kwa sauti bila kukoma, hata unapolala. Mwito huo wa pande mbili ndio jinsi mitandao inavyokupata, inavyokupangia bei na inavyokufuata. Funika simu ndani ya kizimba kinachopitisha umeme, na mwito huo haufiki kamwe. Ukimya si mpangilio. Ni jiometri.", "carry_h2": "Beba.", "carry_p": "Mifuko na pochi nane, zilizoshonwa kwa mkono. Kila moja hufunga kizimba kikamilifu, kwa sababu kizimba cha Faraday chenye pengo ni mfuko tu.", "p_holster": "Huvaliwa kiunoni. Simu hutolewa kwa mwendo mmoja, hufungwa kwa mkunjo mmoja.", "p_sling": "Wa kuvuka mwili, juu kifuani. Funguo, kadi, simu: gizani.", "p_tote": "Mwenzi wa kila siku. Mfuko mmoja wa ndani humeza simu nzima.", "p_sleeve": "Kwa tablet na laptop. Mikutano bila hadhira.", "p_backpack": "Roll-top, lita 20. Mfuko mmoja wa kizimba, eneo lisilo na mawimbi limehakikishwa.", "p_weekender": "Begi la duffel la ukubwa wa kabati la ndege. Kuvuka mipaka bila alama ya data.", "p_keyfob": "Huondoa ufunguo wa gari lako hewani. Wezi wa relay hupata ukimya.", "p_wallet": "Kadi na pesa taslimu. NFC, RFID na skimmers zimefungiwa nje.", "harness_h2": "Mkanda.", "harness_p": "Huvaliwa, haibebwi. Mikanda mitatu inayoweka simu mwilini mwako na nje ya mawimbi hadi utakapoamua vinginevyo.", "p_harness": "Mkanda wa kuvuka mwili wenye pochi ya kizimba. Daima karibu, kamwe mtandaoni.", "p_chestrig": "Mfuko kamili wa kizimba mbele, kamba za matumizi. Rig ya studio na jukwaa.", "p_wrist": "Kamba ya kifundo cha mkono yenye mfuko mdogo wa kizimba. Kwa funguo, kadi, jioni moja tulivu.", "wear_h2": "Vaa.", "wear_p": "Mavazi matano yenye kizimba kilichoshonwa mfukoni, kofiani na pindoni. Unayavaa kama vazi lingine lolote; yanafanya kazi kama hakuna jingine.", "p_hoodie": "Mfuko wa kangaruu ni eneo lisilo na mawimbi. Simu ndani, dunia nje.", "p_parka": "Mifuko mirefu ya kizimba, haipitishi dhoruba nje, haipitishi mawimbi ndani.", "p_cap": "Paneli sita, mfuko mmoja uliofichwa. Kofia tulivu.", "p_beanie": "Imefumwa nje, fedha ndani. Majira ya baridi, bila kufuatiliwa.", "p_scarf": "Huifunika simu uliyosahau kuizima.", "space_h2": "Nafasi.", "space_p": "Vipande vinane kwa nyumbani, ofisini na safarini. Kuanzia pazia linalozima dirisha hadi hema ambamo mazungumzo hubaki mazungumzo.", "p_tent": "Chumba cha faragha kinachojikunjua kwa watu wawili. Hakuna kinachoingia, hakuna kinachotoka.", "p_curtain": "Paneli moja, urefu kamili. Dirisha linaacha kusikiliza.", "p_canopy": "Chandarua cha kitanda cha mtoto. Mlalaji mdogo kabisa, hewa tulivu kabisa.", "p_blanket": "Blanketi kwa sofa. Vifaa vilivyo chini yake vimetoweka.", "p_cone": "Koni ya mezani kwa mikutano. Simu ndani, akili zipo.", "p_sleepbox": "Sanduku la kando ya kitanda. Simu hulala kabla yako.", "p_keybox": "Sanduku la mlangoni. Kila ufunguo wa nyumba, nje ya mawimbi.", "p_router": "Kifuniko cha wifi. Hali ya usiku, inayotekelezwa na fizikia.", "custom_h2": "Maalum. Tunakinga chochote.", "custom_p": "Kila kipande kimetengenezwa kwa mkono na maalum kwa ajili yako. Eleza kinachopaswa kuwa kimya, tunakichora kwa mtindo wetu hapa hapa kwenye chat, na ukishaipenda michoro, watu halisi wanakishona na kukisafirisha duniani kote.", "p_carcover": "Gari lako hutoweka kutoka kila mtandao linapolala.", "p_studio": "Studio za kurekodi, maabara, vyumba vya mikutano. Kuta zinazoshika pumzi zao.", "on_request1": "kwa ombi", "p_research": "Upunguzaji uliopimwa kwa maabara, kliniki na yeyote anayehitaji uhakika.", "on_request2": "kwa ombi", "p_anything": "Mapazia, vifuniko, mavazi, vizimba. Ukiweza kukieleza, tunaweza kukikinga.", "on_request3": "kwa ombi", "custom_cta": "Chora kipande chako mwenyewe", "why_h2": "Kila mtu anafikika. Karibu hakuna anayechagua lini.", "why_p1": "Simu yako huzungumza na minara, setilaiti, beacons na programu saa zote. Hufanya hivi <b>mfukoni mwako, kando ya kitanda chako, katika mikutano yako</b>. Hali ya ndegeni ni ahadi kutoka kwa makampuni yale yale yanayopata pesa kutokana na mahali ulipo. Kizimba cha Faraday si ahadi. Ni fizikia.", "why_p2": "Kila kipande cha Shield kimetengenezwa kwa mkono, kimepambwa ndani kwa kitambaa cha polyamide kilichopakwa fedha kilichofumwa Ujerumani, kinachopunguza 60 dB na zaidi kuanzia 200 MHz hadi 14 GHz: 5G, LTE, GPS, wifi, Bluetooth, NFC. Waandishi wa habari wanaovuka mipaka, wanasheria katika majadiliano, wasanii wa kurekodi, wazazi wanaowafundisha watoto jinsi umakini unavyohisi: wote wanahitaji wakati mmoja ambapo kifaa <b>hakipo tu</b>.", "why_p3": "Kutokuwa na uhakika, kwa makusudi.", "footer_l": "HEISENBAG — Imetengenezwa kwa mkono Berlin, inasafirishwa duniani kote", "chat_fab": "Chora chako", "chat_title": "Eleza kipande chako. Tunakichora.", "chat_btn": "Chora", "chat_hint": "Mchoro ni bure. Ukiupenda, tunakitengeneza kwa mkono na kukisafirisha duniani kote.", "chat_ph": "Kasha la gitaa lililokingwa, ngozi nyeusi…", "chat_wait": "Tunachora, subiri kidogo…", "chat_order": "Agiza kipande hiki", "chat_fail": "Kuchora kumeshindikana, jaribu tena."}, "th": {"nav_how": "หลักการทำงาน", "nav_learn": "เรียนรู้", "nav_carry": "พกพา", "nav_harness": "สายรัด", "nav_wear": "สวมใส่", "nav_space": "พื้นที่", "nav_custom": "สั่งทำ", "hero_h1": "มีสิ่งต่างๆ ลอยวนอยู่รอบตัวมากเกินไป เราปิดกั้นมันไว้ข้างนอก", "hero_p": "ทำมือในเบอร์ลิน สั่งทำเฉพาะสำหรับทุกคน ทุกชิ้นของ Heisenbag Shield มีกรงฟาราเดย์ที่สมบูรณ์ทอแทรกอยู่ในเนื้อผ้า สำหรับโทรศัพท์ของคุณ รถของคุณ สตูดิโอของคุณ บ้านของคุณ ไม่ต้องชาร์จ ไม่ต้องเปิดสวิตช์ ไม่มีแอปให้ต้องไว้ใจ", "hero_cta": "ชมทั้ง 24 ชิ้น", "how_h2": "กรงโลหะ ทอลงในผืนผ้า", "how_p": "ฟิสิกส์นี้มีอายุ 190 ปีและไม่มีใครเอาชนะได้ เราเพียงทำให้มันสวมใส่ได้", "step1": "<b>คลื่นวิทยุคือไฟฟ้าที่อยู่ในอากาศ</b> ทุกการโทร ทุกสัญญาณ GPS ทุกแพ็กเก็ต LTE คือสนามไฟฟ้าที่กำลังค้นหาเสาอากาศของโทรศัพท์คุณ", "step2": "<b>ตาข่ายนำไฟฟ้ากลืนกินสนามไฟฟ้า</b> ซับในของผลิตภัณฑ์ Shield ทุกชิ้นคือผืนผ้าทอละเอียดจากเงินและโลหะ คลื่นที่เข้ามาจะไหลอ้อมรอบ ไม่เคยทะลุผ่าน", "step3": "<b>สิ่งที่เข้ามาไม่ได้ ย่อมติดตามคุณไม่ได้</b> ไม่มีสัญญาณใดไปถึงอุปกรณ์ อุปกรณ์จึงไม่รายงานสิ่งใดเลย ไม่มีตำแหน่ง ไม่มีการเชื่อมต่อกับเสาสัญญาณ ไม่มีข้อมูล", "step4": "<b>ไม่มีแบตเตอรี่ ไม่มีแอป ไม่มีสวิตช์ให้ลืมปิด</b> กรงนี้ทำงานได้เพราะสิ่งที่มันเป็น ไม่ใช่สิ่งที่มันทำ มันไม่อาจถูกอัปเดต ถูกแฮ็ก หรือถูกปิดได้", "learn_h2": "เข้าใจฟิสิกส์", "learn_p": "สามแนวคิดอธิบายทุกสิ่งที่เราทำ เมื่อคุณมองเห็นมันแล้ว คุณจะไม่มีวันมองโทรศัพท์แบบเดิมอีก", "learn1_h": "1. คลื่น", "learn1_p": "คลื่นวิทยุคือแสงที่คุณมองไม่เห็น ทั้งสองคือสิ่งเดียวกัน: สนามไฟฟ้าที่กระเพื่อมผ่านอวกาศ โทรศัพท์ของคุณ wifi ของคุณ ดาวเทียม GPS ของคุณ แสงแดดบนโต๊ะ: คลื่นตระกูลเดียวกัน ต่างกันเพียงความยาว ไม่มีอะไรลึกลับ ทุกอย่างวัดได้", "learn2_h": "2. แสง", "learn2_p": "ปริซึมแยกลำแสงเดียวออกเป็นหลายสี เพราะแต่ละความยาวคลื่นหักเหต่างกัน ความยาวคลื่นเป็นตัวกำหนดทุกอย่าง: คลื่นยาวทะลุผ่านกำแพง คลื่นสั้นนำพาข้อมูล 5G, LTE และ Bluetooth เป็นเพียงสีต่างๆ ของคลื่นวิทยุ และเช่นเดียวกับทุกสี กำแพงสามารถหยุดมันได้", "learn3_h": "3. การส่งสัญญาณ", "learn3_p": "โทรศัพท์ของคุณกับเสาสัญญาณตะโกนหากันตลอดเวลา แม้ในขณะที่คุณหลับ การตะโกนโต้ตอบกันนี้คือวิธีที่เครือข่ายค้นหาคุณ ตีราคาคุณ และติดตามคุณ ห่อโทรศัพท์ไว้ในกรงนำไฟฟ้า แล้วเสียงตะโกนนั้นจะไม่มีวันมาถึง ความเงียบไม่ใช่การตั้งค่า มันคือเรขาคณิต", "carry_h2": "พกพา", "carry_p": "กระเป๋าและซองแปดแบบ เย็บด้วยมือ ทุกใบปิดคลุมกรงได้อย่างสมบูรณ์ เพราะกรงฟาราเดย์ที่มีช่องโหว่ก็เป็นเพียงกระเป๋าใบหนึ่ง", "p_holster": "คาดเอว ดึงโทรศัพท์ออกได้ในจังหวะเดียว ปิดผนึกได้ในการพับครั้งเดียว", "p_sling": "สะพายข้าง สูงบนหน้าอก กุญแจ บัตร โทรศัพท์: มืดสนิท", "p_tote": "คู่หูประจำวัน ช่องด้านในหนึ่งช่องกลืนโทรศัพท์ไว้ทั้งเครื่อง", "p_sleeve": "สำหรับแท็บเล็ตและแล็ปท็อป ประชุมโดยไม่มีผู้ฟังแอบแฝง", "p_backpack": "แบบม้วนปิดด้านบน 20 ลิตร ช่องกรงหนึ่งช่อง รับประกันเขตไร้สัญญาณ", "p_weekender": "กระเป๋าดัฟเฟิลขนาดถือขึ้นเครื่อง ข้ามพรมแดนโดยไม่ทิ้งร่องรอยข้อมูล", "p_keyfob": "ปลดกุญแจรถของคุณออกจากคลื่นในอากาศ โจรรีเลย์จะได้พบเพียงความเงียบ", "p_wallet": "บัตรและเงินสด NFC, RFID และเครื่องสกิมเมอร์ถูกกันไว้ข้างนอก", "harness_h2": "สายรัด", "harness_p": "สวมใส่ ไม่ใช่ถือ สายรัดสามแบบที่เก็บโทรศัพท์ไว้กับตัวคุณและห่างจากคลื่น จนกว่าคุณจะตัดสินใจเป็นอย่างอื่น", "p_harness": "สายรัดสะพายข้างพร้อมซองกรง อยู่ใกล้มือเสมอ ไม่เคยออนไลน์", "p_chestrig": "ช่องกรงเต็มด้านหน้า สายรัดอเนกประสงค์ ชุดสำหรับสตูดิโอและเวที", "p_wrist": "สายรัดข้อมือพร้อมช่องกรงขนาดเล็ก สำหรับกุญแจ บัตร และค่ำคืนที่สงบหนึ่งคืน", "wear_h2": "สวมใส่", "wear_p": "เสื้อผ้าห้าชิ้นที่เย็บกรงไว้ในกระเป๋า ฮู้ด และชายผ้า คุณสวมมันเหมือนเสื้อผ้าทั่วไป แต่มันทำงานไม่เหมือนสิ่งใด", "p_hoodie": "กระเป๋าจิงโจ้คือเขตไร้สัญญาณ โทรศัพท์อยู่ข้างใน โลกอยู่ข้างนอก", "p_parka": "กระเป๋ากรงลึก ภายนอกกันพายุ ภายในกันสัญญาณ", "p_cap": "หกแผง หนึ่งกระเป๋าซ่อน หมวกแห่งความเงียบ", "p_beanie": "ภายนอกถักทอ ภายในเป็นเงิน ฤดูหนาวที่ไม่มีใครติดตาม", "p_scarf": "ห่อหุ้มโทรศัพท์ที่คุณลืมปิด", "space_h2": "พื้นที่", "space_p": "แปดชิ้นสำหรับบ้าน สำนักงาน และการเดินทาง ตั้งแต่ผ้าม่านที่ปิดหน้าต่างให้มืดสนิท ไปจนถึงเต็นท์ที่บทสนทนายังคงเป็นเพียงบทสนทนา", "p_tent": "ห้องส่วนตัวแบบกางได้ทันทีสำหรับสองคน ไม่มีอะไรเข้า ไม่มีอะไรออก", "p_curtain": "หนึ่งแผง ยาวเต็มผืน หน้าต่างเลิกแอบฟัง", "p_canopy": "มุ้งครอบเปลเด็ก ผู้หลับใหลตัวน้อยที่สุด อากาศที่เงียบสงบที่สุด", "p_blanket": "ผ้าห่มสำหรับโซฟา อุปกรณ์ที่อยู่ข้างใต้หายไป", "p_cone": "กรวยตั้งโต๊ะสำหรับการประชุม โทรศัพท์อยู่ข้างใน จิตใจอยู่กับปัจจุบัน", "p_sleepbox": "กล่องข้างเตียง โทรศัพท์หลับก่อนคุณ", "p_keybox": "กล่องหน้าประตู กุญแจทุกดอกในบ้าน ปลอดจากคลื่น", "p_router": "ฝาครอบสำหรับ wifi โหมดกลางคืน บังคับใช้โดยฟิสิกส์", "custom_h2": "สั่งทำ เราป้องกันได้ทุกสิ่ง", "custom_p": "ทุกชิ้นทำมือและสั่งทำเฉพาะสำหรับคุณ บอกเราว่าอะไรควรเงียบ เราจะวาดมันในสไตล์ของเราที่นี่ในแชท และเมื่อคุณหลงรักภาพวาดนั้น ช่างฝีมือตัวจริงจะเย็บและส่งไปทั่วโลก", "p_carcover": "รถของคุณหายไปจากทุกเครือข่ายในขณะที่มันหลับ", "p_studio": "สตูดิโอบันทึกเสียง ห้องแล็บ ห้องประชุม กำแพงที่กลั้นลมหายใจ", "on_request1": "ตามคำขอ", "p_research": "การลดทอนสัญญาณที่วัดค่าได้ สำหรับห้องแล็บ คลินิก และทุกคนที่ต้องการความแน่นอน", "on_request2": "ตามคำขอ", "p_anything": "ผ้าม่าน ผ้าคลุม เสื้อผ้า ตู้ครอบ หากคุณบรรยายได้ เราก็ป้องกันได้", "on_request3": "ตามคำขอ", "custom_cta": "วาดชิ้นงานของคุณเอง", "why_h2": "ทุกคนติดต่อถึงได้ เกือบไม่มีใครได้เลือกว่าเมื่อไร", "why_p1": "โทรศัพท์ของคุณพูดคุยกับเสาสัญญาณ ดาวเทียม บีคอน และแอปตลอดเวลา มันทำเช่นนี้ <b>ในกระเป๋าของคุณ บนโต๊ะข้างเตียงของคุณ ในการประชุมของคุณ</b> โหมดเครื่องบินคือคำสัญญาจากบริษัทเดียวกับที่หาเงินจากตำแหน่งของคุณ กรงฟาราเดย์ไม่ใช่คำสัญญา มันคือฟิสิกส์", "why_p2": "ทุกชิ้นของ Shield ทำมือ บุด้วยผ้าโพลีเอไมด์เคลือบเงินที่ทอในเยอรมนี ลดทอนสัญญาณได้ 60 dB ขึ้นไป ตั้งแต่ 200 MHz ถึง 14 GHz: 5G, LTE, GPS, wifi, Bluetooth, NFC นักข่าวที่เดินทางข้ามพรมแดน ทนายความในการเจรจา ศิลปินในห้องบันทึกเสียง พ่อแม่ที่สอนลูกให้รู้ว่าความใส่ใจเป็นอย่างไร: พวกเขาทุกคนต้องการช่วงเวลาหนึ่งที่อุปกรณ์นั้น <b>ไม่อยู่ตรงนั้นเลย</b>", "why_p3": "ความไม่แน่นอน โดยการออกแบบ", "footer_l": "HEISENBAG — ทำมือในเบอร์ลิน จัดส่งทั่วโลก", "chat_fab": "วาดของคุณ", "chat_title": "บอกเราถึงชิ้นงานของคุณ เราจะวาดให้", "chat_btn": "วาด", "chat_hint": "การวาดไม่มีค่าใช้จ่าย หากคุณชอบ เราจะทำด้วยมือและจัดส่งไปทั่วโลก", "chat_ph": "กล่องกีตาร์ป้องกันสัญญาณ หนังสีเข้ม…", "chat_wait": "กำลังวาด รอสักครู่…", "chat_order": "สั่งชิ้นนี้", "chat_fail": "วาดไม่สำเร็จ โปรดลองอีกครั้ง"}, "tr": {"nav_how": "Nasıl çalışır", "nav_learn": "Fizik", "nav_carry": "Çantalar", "nav_harness": "Koşumlar", "nav_wear": "Giyim", "nav_space": "Mekân", "nav_custom": "Özel yapım", "hero_h1": "Havada uçuşan çok fazla şey var. Biz onları dışarıda bırakıyoruz.", "hero_p": "Berlin'de el yapımı, herkes için özel üretim. Her Heisenbag Shield parçası, kumaşına işlenmiş eksiksiz bir Faraday kafesi taşır. Telefonunuz, arabanız, stüdyonuz, eviniz için. Şarj edilecek bir şey yok, açılacak bir şey yok, güvenilmesi gereken bir uygulama yok.", "hero_cta": "24 parçayı görün", "how_h2": "Kumaşa dokunmuş metal bir kafes.", "how_p": "Bu fizik 190 yaşında ve yenilmez. Biz sadece onu giyilebilir hâle getirdik.", "step1": "<b>Radyo dalgaları, havadaki elektriktir.</b> Her arama, her GPS sinyali, her LTE paketi, telefonunuzun antenini arayan bir elektrik alanıdır.", "step2": "<b>İletken bir örgü elektrik alanlarını yutar.</b> Her Shield ürününün astarı, gümüş ve metalden ince bir dokumadır. Gelen dalgalar onun etrafından akar, asla içinden geçmez.", "step3": "<b>İçeri giremeyen sizi izleyemez.</b> Cihaza hiçbir sinyal ulaşmaz, bu yüzden cihaz hiçbir şey bildirmez: ne konum, ne baz istasyonuyla el sıkışma, ne de veri.", "step4": "<b>Pil yok, uygulama yok, unutulacak bir kapatma düğmesi yok.</b> Kafes, ne yaptığıyla değil, ne olduğuyla çalışır. Güncellenemez, hacklenemez, kapatılamaz.", "learn_h2": "Fiziği öğrenin.", "learn_p": "Ürettiğimiz her şeyi üç fikir açıklıyor. Onları bir kez gördüğünüzde, bir telefona asla eskisi gibi bakmayacaksınız.", "learn1_h": "1. Dalgalar", "learn1_p": "Radyo, göremediğiniz ışıktır. İkisi de aynı şeydir: uzayda dalgalanan elektrik alanları. Telefonunuz, wifi'niz, GPS uydunuz, masadaki güneş ışığı: tek bir dalga ailesi, farklı uzunluklar. Mistik hiçbir şey yok, her şey ölçülebilir.", "learn2_h": "2. Işık", "learn2_p": "Bir prizma tek bir ışını pek çok renge ayırır, çünkü her dalga boyu farklı kırılır. Dalga boyu her şeyi belirler: uzun dalgalar duvarlardan geçer, kısa olanlar veri taşır. 5G, LTE ve Bluetooth radyonun renklerinden ibarettir ve her renk gibi bir duvar onları durdurabilir.", "learn3_h": "3. İletim", "learn3_p": "Telefonunuz ve baz istasyonu, siz uyurken bile birbirine durmadan seslenir. Ağlar sizi bu karşılıklı seslenme sayesinde bulur, fiyatlar ve izler. Telefonu iletken bir kafese sarın; ses asla ulaşmaz. Sessizlik bir ayar değildir. Geometridir.", "carry_h2": "Çantalar.", "carry_p": "Elde dikilmiş sekiz çanta ve kılıf. Her biri kafesin üzerine tamamen kapanır, çünkü aralık bırakan bir Faraday kafesi sadece bir çantadır.", "p_holster": "Kemerde taşınır. Telefon tek hareketle çıkar, tek katlamayla mühürlenir.", "p_sling": "Çapraz askılı, göğüste yüksekte. Anahtarlar, kart, telefon: karanlıkta.", "p_tote": "Günlük çanta. İçindeki tek cep telefonu bütünüyle yutar.", "p_sleeve": "Tablet ve dizüstü bilgisayar için. Seyircisiz toplantılar.", "p_backpack": "Rulo kapaklı, 20 litre. Tek kafes cep, garantili ölü bölge.", "p_weekender": "Kabin boyutunda seyahat çantası. Veri izi bırakmadan sınır geçişleri.", "p_keyfob": "Araba anahtarınızı yayından düşürür. Röle hırsızlarına yalnızca sessizlik kalır.", "p_wallet": "Kartlar ve nakit. NFC, RFID ve kart kopyalayıcılar dışarıda kalır.", "harness_h2": "Koşumlar.", "harness_p": "Taşınmaz, giyilir. Siz aksine karar verene kadar telefonu üzerinizde ve yayın dışında tutan üç koşum.", "p_harness": "Kafesli keseli çapraz koşum. Her zaman elinizin altında, asla çevrimiçi değil.", "p_chestrig": "Tam önden kafes cep, işlevsel kayışlar. Stüdyo ve sahne donanımı.", "p_wrist": "Mini kafes cepli bilek kayışı. Anahtarlar, kartlar ve sakin bir akşam için.", "wear_h2": "Giyim.", "wear_p": "Kafesi cebe, kapüşona ve etek ucuna dikilmiş beş giysi. Onları her şey gibi giyersiniz; hiçbir şey gibi çalışmazlar.", "p_hoodie": "Kanguru cebi bir ölü bölgedir. Telefon içeri, dünya dışarı.", "p_parka": "Derin kafesli cepler. Dışı fırtınaya, içi sinyale dayanıklı.", "p_cap": "Altı panel, tek gizli cep. Sessiz şapka.", "p_beanie": "Dışı örgü, içi gümüş. İzlenmeyen bir kış.", "p_scarf": "Kapatmayı unuttuğunuz telefonu sarar.", "space_h2": "Mekân.", "space_p": "Ev, ofis ve seyahat için sekiz parça. Bir pencereyi karartan perdeden, bir sohbetin sohbet olarak kaldığı çadıra kadar.", "p_tent": "İki kişilik açılır mahremiyet odası. İçeri hiçbir şey, dışarı hiçbir şey.", "p_curtain": "Tek panel, tam boy. Pencere dinlemeyi bırakır.", "p_canopy": "Beşik cibinliği. En küçük uykucu, en sessiz hava.", "p_blanket": "Kanepe için bir örtü. Altındaki cihazlar yok olur.", "p_cone": "Toplantılar için masa üstü koni. Telefonlar içeride, zihinler burada.", "p_sleepbox": "Başucu kutusu. Telefon sizden önce uyur.", "p_keybox": "Antre kutusu. Evdeki her anahtar yayın dışında.", "p_router": "Wifi için bir fanus. Fizikle uygulanan gece modu.", "custom_h2": "Özel yapım. Her şeyi koruyoruz.", "custom_p": "Her parça el yapımıdır ve size özel üretilir. Neyin sessiz olması gerektiğini anlatın, onu kendi tarzımızla tam burada, sohbette çizelim; çizimi sevdiğinizde gerçek insanlar diker ve dünyanın her yerine gönderir.", "p_carcover": "Arabanız uyurken her ağdan kaybolur.", "p_studio": "Kayıt stüdyoları, laboratuvarlar, toplantı odaları. Nefesini tutan duvarlar.", "on_request1": "talep üzerine", "p_research": "Laboratuvarlar, klinikler ve kesinliğe ihtiyaç duyan herkes için ölçülmüş zayıflatma.", "on_request2": "talep üzerine", "p_anything": "Perdeler, örtüler, giysiler, muhafazalar. Tarif edebiliyorsanız, koruyabiliriz.", "on_request3": "talep üzerine", "custom_cta": "Kendi parçanızı çizin", "why_h2": "Herkese ulaşılabilir. Neredeyse hiç kimse ne zaman olacağını seçemez.", "why_p1": "Telefonunuz gece gündüz baz istasyonları, uydular, işaretçiler ve uygulamalarla konuşur. Bunu <b>cebinizde, komodininizde, toplantılarınızda</b> yapar. Uçak modu, konumunuzdan para kazanan şirketlerin verdiği bir sözdür. Faraday kafesi bir söz değildir. Fiziktir.", "why_p2": "Her Shield parçası el yapımıdır ve Almanya'da dokunmuş gümüş kaplı poliamid kumaşla astarlanmıştır; 200 MHz ile 14 GHz arasında 60 dB ve üzeri zayıflatma sağlar: 5G, LTE, GPS, wifi, Bluetooth, NFC. Sınır geçen gazeteciler, müzakeredeki avukatlar, kayıt sanatçıları, çocuklarına dikkatin ne demek olduğunu öğreten ebeveynler: hepsinin ihtiyaç duyduğu tek bir an var: cihazın basitçe <b>orada olmaması</b>.", "why_p3": "Tasarım gereği belirsizlik.", "footer_l": "HEISENBAG — Berlin'de el yapımı, dünyanın her yerine gönderilir", "chat_fab": "Kendininkini çiz", "chat_title": "Parçanızı anlatın. Biz çizelim.", "chat_btn": "Çiz", "chat_hint": "Çizim ücretsizdir. Beğenirseniz, elde üretip dünyanın her yerine göndeririz.", "chat_ph": "Korumalı bir gitar kılıfı, koyu deri…", "chat_wait": "Çiziliyor, bir dakika…", "chat_order": "Bu parçayı sipariş et", "chat_fail": "Çizim başarısız oldu, tekrar deneyin."}, "ur": {"nav_how": "یہ کیسے کام کرتا ہے", "nav_learn": "جانیں", "nav_carry": "ساتھ رکھیں", "nav_harness": "ہارنیس", "nav_wear": "پہنیں", "nav_space": "اسپیس", "nav_custom": "حسبِ فرمائش", "hero_h1": "ہوا میں بہت کچھ اڑ رہا ہے۔ ہم اسے باہر رکھتے ہیں۔", "hero_p": "برلن میں ہاتھ سے بنا، ہر ایک کے لیے ناپ سے بنا۔ ہر Heisenbag Shield پیس کے کپڑے میں ایک مکمل فیراڈے کیج بُنا ہوا ہے۔ آپ کے فون کے لیے، آپ کی گاڑی کے لیے، آپ کے اسٹوڈیو کے لیے، آپ کے گھر کے لیے۔ نہ چارج کرنا، نہ آن کرنا، نہ کسی ایپ پر بھروسا کرنا۔", "hero_cta": "تمام 24 پیس دیکھیں", "how_h2": "دھات کا ایک پنجرہ، کپڑے میں بُنا ہوا۔", "how_p": "یہ طبیعیات 190 سال پرانی ہے اور ناقابلِ شکست ہے۔ ہم نے بس اسے پہننے کے قابل بنا دیا۔", "step1": "<b>ریڈیو لہریں ہوا میں بہتی بجلی ہیں۔</b> ہر کال، ہر GPS پنگ، ہر LTE پیکٹ ایک برقی میدان ہے جو آپ کے فون کا اینٹینا ڈھونڈ رہا ہے۔", "step2": "<b>موصل جالی برقی میدانوں کو نگل جاتی ہے۔</b> ہر Shield پروڈکٹ کا استر چاندی اور دھات کی باریک بُنائی ہے۔ آنے والی لہریں اس کے گرد بہہ جاتی ہیں، کبھی اس کے آر پار نہیں۔", "step3": "<b>جو اندر نہیں آ سکتا، وہ آپ کو ٹریک نہیں کر سکتا۔</b> کوئی سگنل آلے تک نہیں پہنچتا، اس لیے آلہ کچھ رپورٹ نہیں کرتا: نہ لوکیشن، نہ ٹاور سے رابطہ، نہ ڈیٹا۔", "step4": "<b>نہ بیٹری، نہ ایپ، نہ کوئی بند کرنے کا سوئچ جسے آپ بھول جائیں۔</b> یہ پنجرہ اس لیے کام کرتا ہے کہ یہ کیا ہے، اس لیے نہیں کہ یہ کیا کرتا ہے۔ اسے نہ اپ ڈیٹ کیا جا سکتا ہے، نہ ہیک، نہ بند۔", "learn_h2": "طبیعیات کو سمجھیں۔", "learn_p": "تین خیالات ہماری بنائی ہر چیز کی وضاحت کر دیتے ہیں۔ ایک بار انہیں دیکھ لیا تو آپ فون کو پھر کبھی پہلے کی طرح نہیں دیکھیں گے۔", "learn1_h": "1. لہریں", "learn1_p": "ریڈیو وہ روشنی ہے جو آپ دیکھ نہیں سکتے۔ دونوں ایک ہی چیز ہیں: خلا میں لہراتے برقی میدان۔ آپ کا فون، آپ کا wifi، آپ کا GPS سیٹلائٹ، میز پر پڑی دھوپ: لہروں کا ایک ہی خاندان، بس مختلف لمبائیاں۔ کچھ بھی پراسرار نہیں، سب کچھ ناپا جا سکتا ہے۔", "learn2_h": "2. روشنی", "learn2_p": "منشور ایک کرن کو کئی رنگوں میں بانٹ دیتا ہے، کیونکہ ہر طولِ موج الگ انداز سے مڑتا ہے۔ طولِ موج ہی سب کچھ طے کرتا ہے: لمبی لہریں دیواروں کے پار نکل جاتی ہیں، چھوٹی لہریں ڈیٹا اٹھاتی ہیں۔ 5G، LTE اور Bluetooth ریڈیو کے بس مختلف رنگ ہیں، اور ہر رنگ کی طرح، ایک دیوار انہیں روک سکتی ہے۔", "learn3_h": "3. ترسیل", "learn3_p": "آپ کا فون اور ٹاور مسلسل ایک دوسرے کو پکارتے رہتے ہیں، اس وقت بھی جب آپ سو رہے ہوتے ہیں۔ اسی دو طرفہ پکار سے نیٹ ورک آپ کو ڈھونڈتے ہیں، آپ کی قیمت لگاتے ہیں اور آپ کا پیچھا کرتے ہیں۔ فون کو ایک موصل پنجرے میں لپیٹ دیجیے، اور وہ پکار کبھی نہیں پہنچتی۔ خاموشی کوئی سیٹنگ نہیں ہے۔ یہ جیومیٹری ہے۔", "carry_h2": "ساتھ رکھیں۔", "carry_p": "آٹھ بیگ اور پاؤچ، ہاتھ سے سلے ہوئے۔ ہر ایک کیج کے اوپر مکمل طور پر بند ہوتا ہے، کیونکہ جس فیراڈے کیج میں درز ہو، وہ بس ایک بیگ ہے۔", "p_holster": "بیلٹ پر پہنا جاتا ہے۔ ایک حرکت میں فون باہر، ایک تہہ میں بند۔", "p_sling": "کراس باڈی، سینے پر اونچا۔ چابیاں، کارڈ، فون: سب اندھیرے میں۔", "p_tote": "روز کا ساتھی۔ اندر کی ایک جیب فون کو پورا نگل لیتی ہے۔", "p_sleeve": "ٹیبلٹ اور لیپ ٹاپ کے لیے۔ میٹنگز، بغیر کسی سامع کے۔", "p_backpack": "رول ٹاپ، 20 لیٹر۔ ایک کیج جیب، ڈیڈ زون کی ضمانت۔", "p_weekender": "کیبن سائز ڈفل۔ سرحدیں پار کریں، بغیر کسی ڈیٹا کے نشان کے۔", "p_keyfob": "آپ کی گاڑی کی چابی کو ہوا سے ہٹا دیتا ہے۔ ریلے چوروں کو ملتی ہے بس خاموشی۔", "p_wallet": "کارڈ اور نقدی۔ NFC، RFID اور اسکمر، سب باہر۔", "harness_h2": "ہارنیس۔", "harness_p": "پہنا جاتا ہے، اٹھایا نہیں جاتا۔ تین ہارنیس جو فون کو آپ کے جسم پر اور ہوا سے دور رکھتے ہیں، جب تک آپ کچھ اور طے نہ کریں۔", "p_harness": "کیج والے پاؤچ کے ساتھ کراس باڈی ہارنیس۔ ہمیشہ ہاتھ کے قریب، کبھی آن لائن نہیں۔", "p_chestrig": "پورے سامنے کی کیج جیب، یوٹیلیٹی اسٹریپس۔ اسٹوڈیو اور اسٹیج کا رِگ۔", "p_wrist": "منی کیج جیب والا رسٹ اسٹریپ۔ چابیوں، کارڈوں اور ایک پرسکون شام کے لیے۔", "wear_h2": "پہنیں۔", "wear_p": "پانچ ملبوسات، جن کی جیب، ہڈ اور کنارے میں کیج سلا ہوا ہے۔ آپ انہیں کسی بھی اور لباس کی طرح پہنتے ہیں؛ یہ کسی اور چیز کی طرح کام نہیں کرتے۔", "p_hoodie": "کینگرو جیب ایک ڈیڈ زون ہے۔ فون اندر، دنیا باہر۔", "p_parka": "گہری کیج جیبیں، باہر سے طوفان پروف، اندر سے سگنل پروف۔", "p_cap": "چھ پینل، ایک چھپی جیب۔ خاموش ٹوپی۔", "p_beanie": "باہر بُنائی، اندر چاندی۔ سردیاں، بغیر ٹریکنگ کے۔", "p_scarf": "اس فون کو لپیٹ لیتا ہے جسے آپ بند کرنا بھول گئے۔", "space_h2": "اسپیس۔", "space_p": "گھر، دفتر اور سفر کے لیے آٹھ پیس۔ کھڑکی کو مکمل ڈھانپ دینے والے پردے سے لے کر ایک ایسے خیمے تک جہاں گفتگو بس گفتگو ہی رہتی ہے۔", "p_tent": "دو افراد کے لیے پاپ اپ پرائیویسی روم۔ نہ کچھ اندر، نہ کچھ باہر۔", "p_curtain": "ایک پینل، پوری لمبائی۔ کھڑکی سننا بند کر دیتی ہے۔", "p_canopy": "جھولے کی چھتری۔ سب سے ننھا سونے والا، سب سے پرسکون ہوا۔", "p_blanket": "صوفے کے لیے ایک تھرو۔ اس کے نیچے رکھے آلات غائب۔", "p_cone": "میٹنگز کے لیے ٹیبل ٹاپ کون۔ فون اندر، ذہن حاضر۔", "p_sleepbox": "بیڈ سائیڈ باکس۔ فون آپ سے پہلے سو جاتا ہے۔", "p_keybox": "داخلی دروازے کا باکس۔ گھر کی ہر چابی، ہوا سے دور۔", "p_router": "wifi کے لیے ایک ڈھکن۔ نائٹ موڈ، طبیعیات کے ذریعے نافذ۔", "custom_h2": "حسبِ فرمائش۔ ہم کسی بھی چیز کو شیلڈ کر سکتے ہیں۔", "custom_p": "ہر پیس ہاتھ سے بنا ہے اور آپ کے لیے ناپ سے بنا ہے۔ بتائیے کیا خاموش ہونا چاہیے، ہم اسی چیٹ میں اپنے انداز میں اس کا خاکہ بناتے ہیں، اور جب وہ خاکہ آپ کو بھا جائے، تو حقیقی لوگ اسے سیتے ہیں اور دنیا بھر میں بھیجتے ہیں۔", "p_carcover": "جب آپ کی گاڑی آرام کرتی ہے، تو وہ ہر نیٹ ورک سے غائب ہو جاتی ہے۔", "p_studio": "ریکارڈنگ اسٹوڈیو، لیبز، میٹنگ رومز۔ دیواریں جو اپنی سانس روکے رکھتی ہیں۔", "on_request1": "درخواست پر", "p_research": "لیبز، کلینکس اور ہر اس شخص کے لیے ناپی گئی ایٹینیوایشن، جسے یقین درکار ہو۔", "on_request2": "درخواست پر", "p_anything": "پردے، کور، ملبوسات، انکلوژرز۔ اگر آپ اسے بیان کر سکتے ہیں، تو ہم اسے شیلڈ کر سکتے ہیں۔", "on_request3": "درخواست پر", "custom_cta": "اپنا پیس خود بنوائیں", "why_h2": "ہر کوئی پہنچ میں ہے۔ تقریباً کوئی نہیں چنتا کہ کب۔", "why_p1": "آپ کا فون چوبیس گھنٹے ٹاورز، سیٹلائٹس، بیکنز اور ایپس سے بات کرتا رہتا ہے۔ یہ ایسا کرتا ہے <b>آپ کی جیب میں، آپ کی سائیڈ ٹیبل پر، آپ کی میٹنگز میں</b>۔ ایئرپلین موڈ انہی کمپنیوں کا وعدہ ہے جو آپ کی لوکیشن سے کماتی ہیں۔ فیراڈے کیج کوئی وعدہ نہیں۔ یہ طبیعیات ہے۔", "why_p2": "ہر Shield پیس ہاتھ سے بنا ہے، جس میں جرمنی میں بُنا چاندی چڑھا پولی امائیڈ کپڑا لگا ہے، جو 200 MHz سے 14 GHz تک 60 dB اور اس سے زیادہ ایٹینیوایشن دیتا ہے: 5G، LTE، GPS، wifi، Bluetooth، NFC۔ سرحدیں پار کرتے صحافی، مذاکرات میں مصروف وکلا، ریکارڈنگ فنکار، بچوں کو توجہ کا احساس سکھاتے والدین: سب کو ایک ایسے لمحے کی ضرورت ہے جب آلہ بس <b>وہاں نہ ہو</b>۔", "why_p3": "بے یقینی، سوچ سمجھ کر۔", "footer_l": "HEISENBAG — برلن میں ہاتھ سے بنا، دنیا بھر میں بھیجا گیا", "chat_fab": "اپنا بنوائیں", "chat_title": "اپنے پیس کو بیان کریں۔ ہم اس کا خاکہ بنائیں گے۔", "chat_btn": "خاکہ بنائیں", "chat_hint": "خاکہ مفت ہے۔ اگر آپ کو پسند آئے، تو ہم اسے ہاتھ سے بنا کر دنیا بھر میں بھیجتے ہیں۔", "chat_ph": "ایک شیلڈڈ گٹار کیس، گہرا چمڑا…", "chat_wait": "خاکہ بن رہا ہے، ایک لمحہ…", "chat_order": "یہ پیس آرڈر کریں", "chat_fail": "خاکہ نہیں بن سکا، دوبارہ کوشش کریں۔"}, "vi": {"nav_how": "Cách hoạt động", "nav_learn": "Tìm hiểu", "nav_carry": "Mang theo", "nav_harness": "Dây đeo", "nav_wear": "Mặc", "nav_space": "Không gian", "nav_custom": "Đặt riêng", "hero_h1": "Có quá nhiều thứ bay lượn quanh ta. Chúng tôi chặn chúng lại bên ngoài.", "hero_p": "Thủ công tại Berlin, may đo riêng cho mỗi người. Mỗi sản phẩm Heisenbag Shield mang trong mình một lồng Faraday trọn vẹn được dệt vào vải. Cho điện thoại, chiếc xe, phòng thu, ngôi nhà của bạn. Không cần sạc, không cần bật, không ứng dụng nào phải tin tưởng.", "hero_cta": "Xem 24 sản phẩm", "how_h2": "Một chiếc lồng kim loại, dệt vào vải.", "how_p": "Nguyên lý vật lý này đã 190 năm tuổi và không gì vượt qua được. Chúng tôi chỉ biến nó thành thứ có thể mặc lên người.", "step1": "<b>Sóng vô tuyến là điện trong không khí.</b> Mỗi cuộc gọi, mỗi tín hiệu GPS, mỗi gói dữ liệu LTE là một điện trường đang tìm đến ăng-ten điện thoại của bạn.", "step2": "<b>Lưới dẫn điện nuốt chửng điện trường.</b> Lớp lót trong mỗi sản phẩm Shield là một tấm dệt mịn từ bạc và kim loại. Sóng tới chảy vòng quanh nó, không bao giờ xuyên qua.", "step3": "<b>Thứ gì không thể vào thì không thể theo dõi bạn.</b> Không tín hiệu nào chạm tới thiết bị, nên thiết bị chẳng báo cáo gì: không vị trí, không bắt tay với trạm phát, không dữ liệu.", "step4": "<b>Không pin, không ứng dụng, không công tắc nào để quên.</b> Chiếc lồng hoạt động nhờ bản chất của nó, chứ không nhờ điều nó làm. Nó không thể bị cập nhật, bị hack hay bị tắt.", "learn_h2": "Hiểu về vật lý.", "learn_p": "Ba ý tưởng giải thích mọi thứ chúng tôi làm ra. Một khi đã thấy, bạn sẽ không bao giờ nhìn chiếc điện thoại theo cách cũ nữa.", "learn1_h": "1. Sóng", "learn1_p": "Sóng vô tuyến là ánh sáng bạn không thể nhìn thấy. Cả hai là một: điện trường gợn sóng trong không gian. Điện thoại, wifi, vệ tinh GPS của bạn, ánh nắng trên mặt bàn: cùng một họ sóng, chỉ khác bước sóng. Không có gì huyền bí, tất cả đều đo được.", "learn2_h": "2. Ánh sáng", "learn2_p": "Lăng kính tách một chùm sáng thành nhiều màu vì mỗi bước sóng khúc xạ khác nhau. Bước sóng quyết định tất cả: sóng dài xuyên qua tường, sóng ngắn mang dữ liệu. 5G, LTE và Bluetooth chỉ là những màu sắc của sóng vô tuyến, và như mọi màu sắc, một bức tường có thể chặn chúng lại.", "learn3_h": "3. Truyền dẫn", "learn3_p": "Điện thoại của bạn và trạm phát sóng không ngừng gọi nhau, ngay cả khi bạn ngủ. Chính tiếng gọi hai chiều ấy là cách mạng lưới tìm thấy bạn, định giá bạn và đi theo bạn. Bọc điện thoại trong một chiếc lồng dẫn điện, và tiếng gọi ấy không bao giờ tới nơi. Sự im lặng không phải là một tùy chọn cài đặt. Đó là hình học.", "carry_h2": "Mang theo.", "carry_p": "Tám chiếc túi và bao, khâu tay. Mỗi chiếc khép kín hoàn toàn trên lồng, bởi một lồng Faraday có khe hở thì chỉ là một chiếc túi.", "p_holster": "Đeo ở thắt lưng. Rút điện thoại trong một động tác, niêm phong trong một nếp gấp.", "p_sling": "Đeo chéo, cao trước ngực. Chìa khóa, thẻ, điện thoại: tắt lặng.", "p_tote": "Người bạn mỗi ngày. Một ngăn bên trong nuốt trọn chiếc điện thoại.", "p_sleeve": "Cho máy tính bảng và laptop. Những cuộc họp không có khán giả.", "p_backpack": "Nắp cuộn, 20 lít. Một ngăn lồng, vùng chết sóng được đảm bảo.", "p_weekender": "Túi duffel cỡ xách tay lên máy bay. Qua biên giới không để lại dấu vết dữ liệu.", "p_keyfob": "Đưa chìa khóa xe của bạn ra khỏi không trung. Kẻ trộm dùng relay chỉ nhận được im lặng.", "p_wallet": "Thẻ và tiền mặt. NFC, RFID và máy skimmer bị khóa ngoài.", "harness_h2": "Dây đeo.", "harness_p": "Để mặc, không phải để xách. Ba bộ dây đeo giữ điện thoại trên người bạn và ngoài vùng sóng, cho đến khi bạn quyết định khác.", "p_harness": "Dây đeo chéo với bao có lồng. Luôn trong tầm tay, không bao giờ trực tuyến.", "p_chestrig": "Ngăn lồng phủ kín phía trước, dây đai đa năng. Bộ đồ nghề cho phòng thu và sân khấu.", "p_wrist": "Dây đeo cổ tay với ngăn lồng nhỏ. Cho chìa khóa, thẻ, một buổi tối bình yên.", "wear_h2": "Mặc.", "wear_p": "Năm món trang phục với lồng được may vào túi, mũ trùm và gấu áo. Bạn mặc chúng như mọi thứ khác; chúng hoạt động như không gì khác.", "p_hoodie": "Túi kangaroo là một vùng chết sóng. Điện thoại vào trong, thế giới ở ngoài.", "p_parka": "Túi lồng sâu, bên ngoài chống bão, bên trong chống tín hiệu.", "p_cap": "Sáu mảnh, một túi ẩn. Chiếc mũ lặng lẽ.", "p_beanie": "Bên ngoài là len đan, bên trong là bạc. Mùa đông, không bị theo dõi.", "p_scarf": "Bọc lấy chiếc điện thoại bạn quên tắt.", "space_h2": "Không gian.", "space_p": "Tám sản phẩm cho nhà, văn phòng và những chuyến đi. Từ tấm rèm che tối cả khung cửa sổ đến chiếc lều nơi một cuộc trò chuyện vẫn chỉ là cuộc trò chuyện.", "p_tent": "Phòng riêng tư bật mở cho hai người. Không gì vào, không gì ra.", "p_curtain": "Một tấm, dài trọn. Khung cửa sổ thôi lắng nghe.", "p_canopy": "Màn che nôi. Người ngủ nhỏ nhất, bầu không khí yên tĩnh nhất.", "p_blanket": "Một tấm chăn cho sofa. Thiết bị bên dưới biến mất.", "p_cone": "Chóp đặt bàn cho các cuộc họp. Điện thoại vào trong, tâm trí hiện diện.", "p_sleepbox": "Hộp đầu giường. Điện thoại ngủ trước bạn.", "p_keybox": "Hộp ở lối vào. Mọi chìa khóa trong nhà, ngoài vùng sóng.", "p_router": "Chiếc chụp cho wifi. Chế độ ban đêm, được vật lý thực thi.", "custom_h2": "Đặt riêng. Chúng tôi che chắn mọi thứ.", "custom_p": "Mỗi sản phẩm đều thủ công và may đo riêng cho bạn. Hãy mô tả điều gì cần im lặng, chúng tôi sẽ vẽ nó theo phong cách của mình ngay tại đây trong khung chat, và khi bạn đã yêu bản vẽ, những người thợ thật sẽ khâu nó và gửi đi khắp thế giới.", "p_carcover": "Chiếc xe của bạn biến mất khỏi mọi mạng lưới khi nó ngủ.", "p_studio": "Phòng thu âm, phòng thí nghiệm, phòng họp. Những bức tường biết nín thở.", "on_request1": "theo yêu cầu", "p_research": "Độ suy giảm được đo lường cho phòng thí nghiệm, phòng khám và bất kỳ ai cần sự chắc chắn.", "on_request2": "theo yêu cầu", "p_anything": "Rèm, tấm phủ, trang phục, vỏ bọc. Nếu bạn mô tả được, chúng tôi che chắn được.", "on_request3": "theo yêu cầu", "custom_cta": "Vẽ sản phẩm của riêng bạn", "why_h2": "Ai cũng có thể bị liên lạc. Hầu như không ai được chọn khi nào.", "why_p1": "Điện thoại của bạn trò chuyện với trạm phát sóng, vệ tinh, beacon và ứng dụng suốt ngày đêm. Nó làm điều đó <b>trong túi bạn, trên tủ đầu giường bạn, trong các cuộc họp của bạn</b>. Chế độ máy bay là lời hứa từ chính những công ty kiếm tiền từ vị trí của bạn. Lồng Faraday không phải là lời hứa. Đó là vật lý.", "why_p2": "Mỗi sản phẩm Shield đều thủ công, lót bằng vải polyamide mạ bạc dệt tại Đức, suy giảm 60 dB trở lên từ 200 MHz đến 14 GHz: 5G, LTE, GPS, wifi, Bluetooth, NFC. Nhà báo vượt biên giới, luật sư trong các cuộc đàm phán, nghệ sĩ thu âm, cha mẹ dạy con cảm nhận thế nào là sự chú tâm: tất cả đều cần một khoảnh khắc khi thiết bị đơn giản là <b>không có ở đó</b>.", "why_p3": "Sự bất định, theo thiết kế.", "footer_l": "HEISENBAG — Thủ công tại Berlin, giao hàng toàn cầu", "chat_fab": "Vẽ của bạn", "chat_title": "Mô tả sản phẩm của bạn. Chúng tôi sẽ vẽ.", "chat_btn": "Vẽ", "chat_hint": "Bản vẽ miễn phí. Nếu bạn yêu thích, chúng tôi làm thủ công và giao đi khắp thế giới.", "chat_ph": "Một hộp đàn guitar chống sóng, da tối màu…", "chat_wait": "Đang vẽ, xin chờ một chút…", "chat_order": "Đặt sản phẩm này", "chat_fail": "Vẽ không thành công, vui lòng thử lại."}, "zh": {"nav_how": "原理", "nav_learn": "了解", "nav_carry": "随身", "nav_harness": "背带", "nav_wear": "穿戴", "nav_space": "空间", "nav_custom": "定制", "hero_h1": "空中飘荡的信号太多了。我们把它们挡在外面。", "hero_p": "柏林手工制作，为每个人量身定制。每一件 Heisenbag Shield 作品都将完整的法拉第笼织入面料。为你的手机、你的汽车、你的工作室、你的家。无需充电，无需开启，无需信任任何应用。", "hero_cta": "查看全部 24 件作品", "how_h2": "一座金属笼，织进布料里。", "how_p": "这门物理学已有 190 年历史，无可超越。我们只是让它可以穿在身上。", "step1": "<b>无线电波，是空气中的电。</b>每一通电话、每一次 GPS 定位、每一个 LTE 数据包，都是一个正在寻找你手机天线的电场。", "step2": "<b>导电网格吞没电场。</b>每一件 Shield 产品的内衬，都是细密的银质金属编织。来袭的电波绕它而行，从不穿透。", "step3": "<b>进不来的信号，就无法追踪你。</b>没有信号抵达设备，设备便无从上报：没有位置，没有与基站的握手，没有数据。", "step4": "<b>没有电池，没有应用，没有会被遗忘的开关。</b>这只笼子之所以有效，在于它是什么，而非它做什么。它无法被更新、被入侵，也无法被关闭。", "learn_h2": "了解其中的物理。", "learn_p": "三个概念，解释了我们所做的一切。一旦看懂，你看手机的眼光将从此不同。", "learn1_h": "1. 波", "learn1_p": "无线电是你看不见的光。二者本是同一种东西：在空间中荡漾的电场。你的手机、你的 wifi、你的 GPS 卫星、洒在桌上的阳光：同属一个波的家族，只是波长不同。毫不神秘，一切皆可测量。", "learn2_h": "2. 光", "learn2_p": "棱镜把一束光分成许多颜色，因为每种波长的折射各不相同。波长决定一切：长波穿墙而过，短波承载数据。5G、LTE 和 Bluetooth 不过是无线电的不同颜色，而和所有颜色一样，一堵墙就能将它们拦下。", "learn3_h": "3. 传输", "learn3_p": "你的手机和基站一刻不停地彼此呼喊，即使在你熟睡时也是如此。正是这种双向呼喊，让网络找到你、为你定价、跟随你。把手机裹进导电的笼中，呼喊便永远无法抵达。寂静不是一个设置选项。它是几何。", "carry_h2": "随身。", "carry_p": "八款包袋与收纳袋，全部手工缝制。每一款都能将笼体完全闭合，因为有缝隙的法拉第笼，不过是一只普通的包。", "p_holster": "佩于腰间。一个动作取出手机，一次折叠将其封存。", "p_sling": "斜挎，高贴胸前。钥匙、卡片、手机：一片沉寂。", "p_tote": "日常之选。内侧一只口袋，将手机整个吞没。", "p_sleeve": "为平板与笔记本电脑而设。开会时，再无旁听者。", "p_backpack": "卷口设计，20 升容量。一只屏蔽口袋，保证信号盲区。", "p_weekender": "登机尺寸行李袋。穿越国境，不留数据痕迹。", "p_keyfob": "让你的车钥匙从空中消失。中继盗贼只能收到沉默。", "p_wallet": "卡片与现金。NFC、RFID 与盗刷器，一律拒之门外。", "harness_h2": "背带。", "harness_p": "穿在身上，而非拎在手里。三款背带让手机贴身而行，远离电波，直到你另作决定。", "p_harness": "斜挎背带配屏蔽小袋。随手可及，从不在线。", "p_chestrig": "整面前置屏蔽口袋，配功能织带。为工作室与舞台而生。", "p_wrist": "腕带配迷你屏蔽口袋。容纳钥匙、卡片，和一个安静的夜晚。", "wear_h2": "穿戴。", "wear_p": "五款服装，屏蔽笼缝入口袋、兜帽与下摆。你像穿任何衣服一样穿着它们；它们却以无可替代的方式发挥作用。", "p_hoodie": "袋鼠口袋即信号盲区。手机放进去，世界关在外。", "p_parka": "深邃的屏蔽口袋，外可抵御风暴，内可隔绝信号。", "p_cap": "六片拼接，一只隐藏口袋。一顶安静的帽子。", "p_beanie": "外层针织，内里银线。冬日，无迹可寻。", "p_scarf": "裹住那部你忘了关机的手机。", "space_h2": "空间。", "space_p": "八件作品，为家、办公室与旅途而设。从遮蔽整扇窗户的帘幕，到一顶让对话始终只属于对话者的帐篷。", "p_tent": "可快速展开的双人隐私空间。什么都进不来，什么都出不去。", "p_curtain": "一整幅落地帘。窗户不再倾听。", "p_canopy": "婴儿床罩帐。最小的睡眠者，最安静的空气。", "p_blanket": "一条沙发盖毯。盖在下面的设备，就此消失。", "p_cone": "会议用桌面罩锥。手机放进去，心思留下来。", "p_sleepbox": "床头盒。手机比你先入睡。", "p_keybox": "玄关盒。家中每一把钥匙，都远离电波。", "p_router": "为 wifi 准备的罩子。夜间模式，由物理强制执行。", "custom_h2": "定制。我们可以屏蔽一切。", "custom_p": "每一件作品都是手工制作，为你量身定制。描述你希望什么安静下来，我们就在这个对话里以我们的风格把它画出来；当你爱上这幅图，真实的手艺人会将它缝制完成，并寄往世界各地。", "p_carcover": "当你的车停歇时，它将从所有网络中消失。", "p_studio": "录音室、实验室、会议室。屏住呼吸的墙壁。", "on_request1": "按需定制", "p_research": "为实验室、诊所以及所有需要确定性的人，提供实测衰减数据。", "on_request2": "按需定制", "p_anything": "帘幕、罩套、服装、封闭空间。只要你能描述，我们就能屏蔽。", "on_request3": "按需定制", "custom_cta": "画出你自己的作品", "why_h2": "人人都可被联系到。却几乎没人能选择何时。", "why_p1": "你的手机昼夜不停地与基站、卫星、信标和应用对话。它就在<b>你的口袋里、床头柜上、会议之中</b>。飞行模式，是那些将你的位置变现的公司给出的承诺。法拉第笼不是承诺。它是物理。", "why_p2": "每一件 Shield 作品均为手工制作，内衬德国织造的镀银聚酰胺面料，在 200 MHz 至 14 GHz 范围内衰减 60 dB 以上：5G、LTE、GPS、wifi、Bluetooth、NFC。穿越国境的记者、谈判中的律师、录音艺术家、教孩子体会专注为何物的父母：他们都需要那样一个时刻，设备只是<b>不在那里</b>。", "why_p3": "不确定性，源于设计。", "footer_l": "HEISENBAG — 柏林手工制作，寄往世界各地", "chat_fab": "画出你的", "chat_title": "描述你的作品。我们来画。", "chat_btn": "画", "chat_hint": "绘图免费。如果你喜欢，我们会手工制作并寄往世界各地。", "chat_ph": "一只屏蔽吉他琴盒，深色皮革……", "chat_wait": "正在绘制，请稍候……", "chat_order": "订购这件作品", "chat_fail": "绘制失败，请重试。"}};
